export const demos = [
	{ name: 'Button', category: 'actions', description: "Clickable action with variants, sizes, shapes, loading and icon slots.", docs: "`Button` runs an action on click, Enter or Space. It is a focusable `div`, so it works anywhere in a GPUI tree.\n\n```svelte\n<script>\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n</script>\n\n<Button label=\"Save\" onclick={save} />\n<Button variant=\"danger\" size=\"h-md\" shape=\"square\">Delete</Button>\n<Button variant=\"ghost\" loading={busy} shape=\"modern\" label=\"Sync\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — | Content; `label` is the plain-text shorthand. |\n| `label` | `string` | `''` |   |\n| `variant` | `'primary' \\| 'secondary' \\| 'themed' \\| 'outline' \\| 'ghost' \\| 'link' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'primary'` | Fractalstyler's variant axis. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` | Fractalstyler's size axis. |\n| `shape` | `'square' \\| 'min' \\| 'modern' \\| 'curved' \\| 'round'` | `'min'` |   |\n| `disabled` | `boolean` | `false` |   |\n| `loading` | `boolean` | `false` | Shows `…` in place of the content and swallows clicks. |\n| `full` | `boolean` | `false` | Stretches to the parent's width. |\n| `leading` | `Snippet` | — | Snippet before the content, usually an icon. |\n| `trailing` | `Snippet` | — |   |\n| `onclick` | `(e: GpuixEvent) => void` | — |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Activate while focused |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tlet clicks = $state(0);\n\tconst variants = ['primary', 'secondary', 'themed', 'outline', 'ghost', 'link', 'info', 'success', 'warning', 'danger'] as const;\n\tconst shapes = ['square', 'min', 'modern', 'curved', 'round'] as const;\n\tconst sizes = ['h-sm', 'h-md', 'h-bs', 'h-lg', 'h-xl'] as const;\n\n</script>\n\n{#snippet plus()}<div>+</div>{/snippet}\n{#snippet arrow()}<div>→</div>{/snippet}\n\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n\t<div style=\"display: flex; flex-direction: row; flex-wrap: wrap; gap: 8px\">\n\t\t{#each variants as v}\n\t\t\t<Button variant={v} label={v} onclick={() => clicks++} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each shapes as s}\n\t\t\t<Button shape={s} label={s} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each sizes as z}\n\t\t\t<Button size={z} label={z} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"Save\" leading={plus} />\n\t\t<Button label=\"Next\" trailing={arrow} />\n\t\t<Button label=\"Full width\" full />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"Disabled\" disabled />\n\t\t<Button label=\"Loading\" loading />\n\t</div>\n\t<div>clicks: {clicks}</div>\n</div>\n```\n\n## GPUI notes\n\n- The focus ring is a border colour change, since GPUI has no outline or shadow.\n- Disabled buttons drop their hover rule rather than overriding it, because a `:hover` rule outranks a plain class.", demo: Button },
	{ name: 'ButtonGroup', category: 'actions', description: "Row of attached buttons, or a segmented single-select control driven by options and value.", docs: "`ButtonGroup` has two modes. Give it `options` for a segmented, single-select control. Give it children to lay buttons out in a row.\n\n```svelte\n<script>\n  import ButtonGroup from 'gpuix-fractalsvelte-ui/ButtonGroup.svelte';\n  let range = $state('week');\n</script>\n\n<ButtonGroup\n  options={[\n    { value: 'day', label: 'Day' },\n    { value: 'week', label: 'Week' },\n    { value: 'year', label: 'Year', disabled: true }\n  ]}\n  value={range}\n  onchange={(v) => (range = v)}\n/>\n\n<ButtonGroup>\n  <Button variant=\"outline\" label=\"Left\" />\n  <Button variant=\"outline\" label=\"Right\" />\n</ButtonGroup>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — | Attached mode: the child buttons laid out edge to edge. |\n| `options` | `Option[]` | — | Segmented mode: one selectable segment per option. Use instead of `children`. |\n| `value` | `T \\| null` | — |   |\n| `onchange` | `(value: T) => void` | — |   |\n| `variant` | `'primary' \\| 'secondary' \\| 'themed' \\| 'outline' \\| 'ghost' \\| 'link' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'primary'` | Fractalstyler's variant for the selected segment. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` | Fractalstyler's size axis. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `border`, `radius-md`, `radius-sm`, `ring`, `text-secondary`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Tab | Moves focus to the segmented group (one stop) |\n| Left, Up | Select the previous enabled option, wrapping |\n| Right, Down | Select the next enabled option, wrapping |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\timport ButtonGroup from 'gpuix-fractalsvelte-ui/ButtonGroup.svelte';\n\ttype Range = 'day' | 'week' | 'month' | 'year';\n\tlet range = $state<Range>('week');\n\tlet view = $state('list');\n\tlet align = $state('left');\n\tconst views = [\n\t\t{ value: 'list', label: 'List' },\n\t\t{ value: 'board', label: 'Board' },\n\t\t{ value: 'graph', label: 'Graph' }\n\t];\n\tconst aligns = [\n\t\t{ value: 'left', label: 'Left' },\n\t\t{ value: 'centre', label: 'Centre' },\n\t\t{ value: 'right', label: 'Right' }\n\t];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<ButtonGroup\n\t\t\toptions={[\n\t\t\t\t{ value: 'day', label: 'Day' },\n\t\t\t\t{ value: 'week', label: 'Week' },\n\t\t\t\t{ value: 'month', label: 'Month' },\n\t\t\t\t{ value: 'year', label: 'Year', disabled: true }\n\t\t\t]}\n\t\t\tvalue={range}\n\t\t\tonchange={(v: Range) => (range = v)}\n\t\t/>\n\t\t<div style=\"color: var(--text-secondary)\">range: {range}</div>\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<ButtonGroup options={views} value={view} onchange={(v) => (view = v)} variant=\"secondary\" size=\"h-md\" />\n\t\t<ButtonGroup options={views} value={view} onchange={(v) => (view = v)} variant=\"success\" size=\"h-lg\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<ButtonGroup options={aligns} value={align} onchange={(v) => (align = v)} variant=\"warning\" />\n\t\t<ButtonGroup options={aligns} value={align} onchange={(v) => (align = v)} variant=\"danger\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 0\">\n\t\t<ButtonGroup>\n\t\t\t{#snippet children()}\n\t\t\t\t<Button variant=\"outline\" size=\"h-md\" label=\"Undo\" />\n\t\t\t\t<Button variant=\"outline\" size=\"h-md\" label=\"Redo\" />\n\t\t\t\t<Button variant=\"outline\" size=\"h-md\" label=\"Reset\" />\n\t\t\t{/snippet}\n\t\t</ButtonGroup>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- Segmented mode is one focusable track, not one tab stop per segment, as in a native radio group.\n- In attached mode, `Button`, `IconButton` and `Toggle` children join automatically. Through context they learn whether they are first, middle or last, square their inner corners, and overlap borders by 1px so seams never double. Other children are laid out edge to edge unchanged.", demo: ButtonGroup },
	{ name: 'IconButton', category: 'actions', description: "Square icon-only action with a hover tooltip, sharing Button's variants and sizes.", docs: "`IconButton` is a square `Button` for a single icon. Give it a `label` and hovering shows a tooltip. Like `Button`, it is a focusable `div`.\n\n```svelte\n<script>\n  import IconButton from 'gpuix-fractalsvelte-ui/IconButton.svelte';\n</script>\n\n<IconButton glyph=\"+\" label=\"Add\" onclick={add} />\n<IconButton variant=\"danger\" label=\"Delete\">\n  {#snippet children()}🗑{/snippet}\n</IconButton>\n<IconButton glyph=\"✕\" size=\"h-md\" disabled />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — | The icon; `glyph` is the plain-text shorthand. |\n| `glyph` | `string` | `''` |   |\n| `label` | `string` | `''` | Tooltip text shown after a short hover. |\n| `variant` | `'primary' \\| 'secondary' \\| 'themed' \\| 'outline' \\| 'ghost' \\| 'link' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'ghost'` | Fractalstyler's variant axis. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` | Fractalstyler's size axis; the button is a square of that height. |\n| `shape` | `'square' \\| 'min' \\| 'modern' \\| 'curved' \\| 'round'` | `'min'` |   |\n| `disabled` | `boolean` | `false` |   |\n| `onclick` | `(e: GpuixEvent) => void` | — |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Activate while focused |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport IconButton from 'gpuix-fractalsvelte-ui/IconButton.svelte';\n\tlet added = $state(0);\n\tconst variants = ['primary', 'secondary', 'themed', 'outline', 'ghost', 'link', 'info', 'success', 'warning', 'danger'] as const;\n\tconst sizes = ['h-sm', 'h-md', 'h-bs', 'h-lg', 'h-xl'] as const;\n\tconst shapes = ['square', 'min', 'modern', 'curved', 'round'] as const;\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: row; flex-wrap: wrap; gap: 8px\">\n\t\t{#each variants as v}\n\t\t\t<IconButton variant={v} glyph=\"+\" label={v} onclick={() => added++} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each shapes as s}\n\t\t\t<IconButton shape={s} variant=\"outline\" glyph=\"+\" label={s} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each sizes as z}\n\t\t\t<IconButton size={z} glyph=\"✕\" label={z} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<IconButton glyph=\"−\" label=\"Disabled\" disabled />\n\t\t<IconButton variant=\"themed\" label=\"Star\">\n\t\t\t{#snippet children()}★{/snippet}\n\t\t</IconButton>\n\t</div>\n\t<div>added: {added}</div>\n</div>\n```\n\n## GPUI notes\n\n- The tooltip wraps the button with `Tooltip` and spreads its hover handlers onto the button. A button with its own `onclick` would otherwise block the hover.\n- The focus ring is a border colour change, since GPUI has no outline or shadow.\n- Disabled buttons drop their hover rule rather than overriding it.", demo: IconButton },
	{ name: 'Link', category: 'actions', description: "Inline text action with variants, underlined on hover.", docs: "`Link` is a text action that looks like a link. It is a focusable `div`, so it runs an action on click, Enter or Space like `Button`.\n\n```svelte\n<script>\n  import Link from 'gpuix-fractalsvelte-ui/Link.svelte';\n</script>\n\n<Link label=\"Read the docs\" onclick={openDocs} />\n<Link variant=\"danger\" size=\"h-md\" label=\"Remove\" onclick={remove} />\n<Link disabled label=\"Unavailable\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `label` | `string` | `''` |   |\n| `variant` | `'themed' \\| 'secondary' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'themed'` | Text colour, in fractalstyler's names; `secondary` is plain ink. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` |   |\n| `disabled` | `boolean` | `false` |   |\n| `onclick` | `(e: GpuixEvent) => void` | — |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`danger`, `danger-hover`, `info`, `radius-sm`, `ring`, `success`, `text-primary`, `theme-color`, `theme-color-alt`, `warning`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Activate while focused |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Link from 'gpuix-fractalsvelte-ui/Link.svelte';\n\tlet last = $state('none');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 14px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center\">\n\t\t{#each ['themed', 'secondary', 'info', 'success', 'warning', 'danger'] as const as variant}\n\t\t\t<Link {variant} label={variant} onclick={() => (last = variant)} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center\">\n\t\t<Link size=\"h-sm\" label=\"Small\" onclick={() => (last = 'small')} />\n\t\t<Link size=\"h-md\" label=\"Medium\" onclick={() => (last = 'medium')} />\n\t\t<Link size=\"h-lg\" label=\"Large\" onclick={() => (last = 'large')} />\n\t\t<Link label=\"Disabled\" disabled />\n\t</div>\n\t<div style=\"color: var(--text-secondary)\">last clicked: {last}</div>\n</div>\n```\n\n## GPUI notes\n\n- The hover underline is `text-decoration`, which GPUI inherits to the text.\n- The root hugs its text (`align-self: flex-start`), so only the text is clickable, not the full row.\n- The focus ring is a border colour change, since GPUI has no outline.", demo: Link },
	{ name: 'Toggle', category: 'actions', description: "Button that holds a pressed or unpressed state, with a `pressedVariant` for the pressed look.", docs: "`Toggle` is a button with two states. It is controlled, so the parent owns `pressed` and updates it in `onchange`.\n\n```svelte\n<script>\n  import Toggle from 'gpuix-fractalsvelte-ui/Toggle.svelte';\n  let bold = $state(false);\n</script>\n\n<Toggle label=\"Bold\" pressed={bold} onchange={(p) => (bold = p)} />\n<Toggle pressedVariant=\"success\" label=\"Wrap\" pressed={wrap} onchange={(p) => (wrap = p)} />\n<Toggle label=\"Locked\" disabled pressed />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `label` | `string` | `''` |   |\n| `pressed` | `boolean` | `false` | Whether the toggle is on. Pair with `onchange`. |\n| `onchange` | `(pressed: boolean) => void` | — | Called with the next pressed state. |\n| `variant` | `'outline' \\| 'ghost'` | `'outline'` |   |\n| `pressedVariant` | `'themed' \\| 'secondary' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'themed'` | Colour of the pressed state, in fractalstyler's names. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` | Fractalstyler's height steps. |\n| `disabled` | `boolean` | `false` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `border-strong`, `danger`, `danger-soft`, `info`, `info-soft`, `radius-md`, `ring`, `success`, `success-soft`, `text-primary`, `text-secondary`, `theme-color`, `theme-color-sub`, `warning`, `warning-soft`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Flip the state while focused |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Toggle from 'gpuix-fractalsvelte-ui/Toggle.svelte';\n\tlet bold = $state(false);\n\tlet italic = $state(true);\n\tlet wrap = $state(false);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Toggle label=\"Bold\" pressed={bold} onchange={(p) => (bold = p)} />\n\t\t<Toggle label=\"Italic\" pressed={italic} onchange={(p) => (italic = p)} pressedVariant=\"secondary\" />\n\t\t<Toggle label=\"Wrap\" pressed={wrap} onchange={(p) => (wrap = p)} pressedVariant=\"success\" variant=\"ghost\" />\n\t\t<Toggle label=\"Locked\" pressed disabled pressedVariant=\"danger\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each ['themed', 'secondary', 'info', 'success', 'warning', 'danger'] as const as pressedVariant}\n\t\t\t<Toggle pressedVariant={pressedVariant} label={pressedVariant} pressed={pressedVariant !== 'secondary'} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Toggle size=\"h-md\" label=\"Small\" pressed />\n\t\t<Toggle size=\"h-bs\" label=\"Medium\" pressed />\n\t\t<Toggle size=\"h-lg\" label=\"Large\" pressed />\n\t</div>\n\t<div style=\"color: var(--text-secondary)\">bold: {bold ? 'on' : 'off'} · italic: {italic ? 'on' : 'off'} · wrap: {wrap ? 'on' : 'off'}</div>\n</div>\n```\n\n## GPUI notes\n\n- The pressed state changes the fill and text colour only, so the focus ring on the border still shows on a pressed toggle.\n- Disabled toggles drop their hover rule rather than overriding it.", demo: Toggle },
	{ name: 'Checkbox', category: 'inputs', description: "Boolean or indeterminate check with a label, in three sizes, controlled by the parent.", docs: "`Checkbox` is controlled: it shows `checked` and calls `onchange` with the next state. The parent stores the value.\n\n```svelte\n<script>\n  import Checkbox from 'gpuix-fractalsvelte-ui/Checkbox.svelte';\n  let agree = $state(false);\n  let all = $state(false);\n</script>\n\n<Checkbox label=\"Accept terms\" checked={agree} onchange={(v) => (agree = v)} />\n<Checkbox label=\"Select all\" indeterminate={!all && someSelected} onchange={(v) => (all = v)} />\n<Checkbox label=\"Locked\" checked disabled />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `checked` | `boolean` | `false` |   |\n| `indeterminate` | `boolean` | `false` | Shows a dash in place of the tick. The parent decides what a click means, and clears it. |\n| `onchange` | `(checked: boolean) => void` | — | Called with the next checked state when the box or label is clicked, or Space is pressed. |\n| `label` | `string` | `''` | Plain-text label, ignored when `children` is given. |\n| `children` | `Snippet` | — |   |\n| `disabled` | `boolean` | `false` |   |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs'` | `'h-sm'` | Fractalstyler's height steps; the box is that height square. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-surface`, `border-strong`, `radius-sm`, `ring`, `text-md`, `text-primary`, `text-theme`, `theme-color`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Space | Toggle while focused |\n\nEnter is not handled.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Checkbox from 'gpuix-fractalsvelte-ui/Checkbox.svelte';\n\n\tlet items = $state([true, false, true]);\n\tconst all = $derived(items.every(Boolean));\n\tconst some = $derived(items.some(Boolean) && !all);\n\tlet terms = $state(false);\n</script>\n\n<div style=\"display: flex; flex-direction: row; gap: 48px\">\n\t<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t\t<Checkbox label=\"Small\" size=\"h-sm\" checked />\n\t\t<Checkbox label=\"Medium\" size=\"h-md\" checked={terms} onchange={(v) => (terms = v)} />\n\t\t<Checkbox label=\"Large\" size=\"h-bs\" checked />\n\t\t<Checkbox label=\"Indeterminate\" indeterminate />\n\t\t<Checkbox label=\"Disabled\" disabled />\n\t\t<Checkbox label=\"Disabled checked\" disabled checked />\n\t</div>\n\n\t<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t\t<Checkbox\n\t\t\tlabel=\"Select all\"\n\t\t\tchecked={all}\n\t\t\tindeterminate={some}\n\t\t\tonchange={(v) => (items = items.map(() => v))}\n\t\t/>\n\t\t{#each items as on, i (i)}\n\t\t\t<div style=\"padding-left: 24px\">\n\t\t\t\t<Checkbox label=\"Item {i + 1}\" checked={on} onchange={(v) => (items[i] = v)} />\n\t\t\t</div>\n\t\t{/each}\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- The root has `hitbox=\"self\"`, so clicks on the box or label reach the row.\n- The tick and dash are inline SVGs. They take their colour from `currentColor` via the `.mark` class.\n- Focus is a border colour change on the box, since GPUI has no outline.\n- A disabled row has `tabindex` -1 and no click handler effect; the `onchange` is never called.", demo: Checkbox },
	{ name: 'RadioGroup', category: 'inputs', description: "Pick one of a few options, in a column or a row, with arrow-key navigation.", docs: "`RadioGroup` shows a set of options and reports the one the user picks. Each option is a focusable `div`, so arrow keys and Space work in any GPUI tree.\n\n```svelte\n<script>\n  import RadioGroup from 'gpuix-fractalsvelte-ui/RadioGroup.svelte';\n  let plan = $state('monthly');\n</script>\n\n<RadioGroup\n  options={[\n    { value: 'monthly', label: 'Monthly' },\n    { value: 'yearly', label: 'Yearly' },\n    { value: 'lifetime', label: 'Lifetime', disabled: true }\n  ]}\n  value={plan}\n  onchange={(v) => (plan = v)}\n/>\n<RadioGroup options={views} value={view} direction=\"row\" onchange={(v) => (view = v)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `options` | `Option[]` | — |   |\n| `value` | `string \\| null` | — | The checked option's value, or `null` for none. |\n| `onchange` | `(value: string) => void` | — |   |\n| `direction` | `'row' \\| 'column'` | `'column'` |   |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs'` | `'h-sm'` | Fractalstyler's height steps; each circle is that height square. |\n| `disabled` | `boolean` | `false` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-surface`, `border-strong`, `radius-full`, `ring`, `text-md`, `text-primary`, `theme-color`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Down, Right | Select the next enabled option, wrapping at the end |\n| Up, Left | Select the previous enabled option, wrapping at the start |\n| Space | Select the focused option |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport RadioGroup from 'gpuix-fractalsvelte-ui/RadioGroup.svelte';\n\tconst plans = [\n\t\t{ value: 'monthly', label: 'Monthly' },\n\t\t{ value: 'yearly', label: 'Yearly' },\n\t\t{ value: 'lifetime', label: 'Lifetime', disabled: true }\n\t];\n\tconst views = [\n\t\t{ value: 'list', label: 'List' },\n\t\t{ value: 'grid', label: 'Grid' },\n\t\t{ value: 'board', label: 'Board' }\n\t];\n\tlet plan = $state<string | null>('monthly');\n\tlet view = $state<string | null>('grid');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 20px; padding: 8px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 48px; align-items: start\">\n\t\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Column · md · one disabled option</div>\n\t\t\t<RadioGroup options={plans} value={plan} onchange={(v) => (plan = v)} />\n\t\t</div>\n\t\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Sizes</div>\n\t\t\t<RadioGroup options={plans.slice(0, 2)} value={plan} size=\"h-sm\" onchange={(v) => (plan = v)} />\n\t\t\t<RadioGroup options={plans.slice(0, 2)} value={plan} size=\"h-bs\" onchange={(v) => (plan = v)} />\n\t\t</div>\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Row</div>\n\t\t<RadioGroup options={views} value={view} direction=\"row\" onchange={(v) => (view = v)} />\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Disabled group</div>\n\t\t<RadioGroup options={views} value=\"list\" direction=\"row\" disabled />\n\t</div>\n\t<div style=\"color: var(--text-secondary)\">plan: {plan} · view: {view}</div>\n</div>\n```\n\n## GPUI notes\n\n- The focus ring is a border colour change on the circle, since GPUI has no outline or shadow.\n- Arrow keys move focus with the selection through `get_native().focusElement`, which works in headless tests too. The `focus_element` window helper is a no-op headless.\n- Every enabled option is a tab stop, so Tab visits each one. A roving tab stop (one per group) would match native radios more closely; it is not implemented.", demo: RadioGroup },
	{ name: 'Select', category: 'inputs', description: "Dropdown that picks one option from a list, with keyboard navigation and a scrolling list for long option sets.", docs: "`Select` shows the chosen option in a trigger and opens a list beside it. The list is a `Popover`, so it closes on an outside press and on Escape.\n\n```svelte\n<script>\n  import Select from 'gpuix-fractalsvelte-ui/Select.svelte';\n  let fruit = $state(null);\n</script>\n\n<Select\n  options={[\n    { value: 'apple', label: 'Apple' },\n    { value: 'banana', label: 'Banana' },\n    { value: 'date', label: 'Date', disabled: true }\n  ]}\n  value={fruit}\n  onchange={(v) => (fruit = v)}\n  placeholder=\"Pick a fruit\"\n/>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `options` | `Option[]` | — |   |\n| `value` | `string \\| null` | — | The chosen option's value, or `null` to show the placeholder. |\n| `onchange` | `(value: string) => void` | — |   |\n| `placeholder` | `string` | `'Select…'` |   |\n| `size` | `'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-lg'` | Fractalstyler's height steps for the trigger and rows. |\n| `disabled` | `boolean` | `false` |   |\n| `style` | `string \\| null` | — | Inline CSS for the trigger; `width` defaults to 200px. |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `border-strong`, `radius-md`, `radius-sm`, `ring`, `text-muted`, `text-primary`, `text-secondary`, `theme-color`\n## Keyboard\n\n| Key | Closed | Open |\n| --- | --- | --- |\n| Enter, Space, Down, Up | Open the list | Enter and Space pick the highlighted option |\n| Down | — | Highlight the next enabled option |\n| Up | — | Highlight the previous enabled option |\n| Escape | — | Close without changing the value |\n| Tab | — | Close |\n\nFocus stays on the trigger while the list is open. The arrow keys move a highlight, not focus.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Select from 'gpuix-fractalsvelte-ui/Select.svelte';\n\n\tconst fruits = [\n\t\t{ value: 'apple', label: 'Apple' },\n\t\t{ value: 'banana', label: 'Banana' },\n\t\t{ value: 'cherry', label: 'Cherry' },\n\t\t{ value: 'date', label: 'Date', disabled: true },\n\t\t{ value: 'elder', label: 'Elderberry' }\n\t];\n\tconst zones = Array.from({ length: 24 }, (_, i) => ({ value: `z${i + 1}`, label: `Zone ${i + 1}` }));\n\n\tlet fruit = $state<string | null>(null);\n\tlet zone = $state<string | null>('z3');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px; padding: 8px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<Select options={fruits} value={fruit} onchange={(v) => (fruit = v)} placeholder=\"Pick a fruit\" size=\"h-md\" />\n\t\t<Select options={fruits} value={fruit} onchange={(v) => (fruit = v)} placeholder=\"Pick a fruit\" />\n\t\t<Select options={fruits} value={fruit} onchange={(v) => (fruit = v)} placeholder=\"Pick a fruit\" size=\"h-xl\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<Select options={fruits} value=\"banana\" disabled />\n\t\t<Select options={zones} value={zone} onchange={(v) => (zone = v)} placeholder=\"Long list\" />\n\t</div>\n\t<div style=\"color: var(--text-secondary)\">fruit: {fruit ?? 'none'} · zone: {zone ?? 'none'}</div>\n</div>\n```\n\n## GPUI notes\n\n- The panel's colours come from the fractalstyler tokens in `style`, since `Popover`'s own fallbacks are dark and would show in the light theme.\n- Opening the list highlights the chosen option, or the first enabled one.\n- The highlighted row is scrolled into view with `get_native().scrollIntoView`, which the headless renderer does not implement, so that scroll is only verified in a window.", demo: Select },
	{ name: 'Slider', category: 'inputs', description: "Pick a number in a range by dragging the thumb, clicking the track or using the arrow keys.", docs: "`Slider` maps a value between `min` and `max` onto a horizontal track. Dragging, clicking and the keyboard all report through `onchange`.\n\n```svelte\n<script>\n  import Slider from 'gpuix-fractalsvelte-ui/Slider.svelte';\n  let volume = $state(40);\n</script>\n\n<Slider value={volume} onchange={(v) => (volume = v)} />\n<Slider value={level} min={0} max={10} step={2} size=\"h-sm\" onchange={(v) => (level = v)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `value` | `number` | — |   |\n| `onchange` | `(value: number) => void` | — |   |\n| `min` | `number` | `0` |   |\n| `max` | `number` | `100` |   |\n| `step` | `number` | `1` | Values snap to `min + n * step`. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs'` | `'h-md'` | Fractalstyler's height steps for the control. |\n| `disabled` | `boolean` | `false` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `height-bs`, `height-md`, `height-sm`, `radius-full`, `ring`, `theme-color`, `theme-color-sub`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Right, Up | Step up by `step` |\n| Left, Down | Step down by `step` |\n| Home | Jump to `min` |\n| End | Jump to `max` |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Slider from 'gpuix-fractalsvelte-ui/Slider.svelte';\n\tlet volume = $state(40);\n\tlet brightness = $state(70);\n\tlet level = $state(4);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 20px; padding: 8px; width: 360px\">\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"display: flex; flex-direction: row; justify-content: space-between; color: var(--text-secondary); font-size: var(--text-sm)\">\n\t\t\t<div>Volume</div><div>{volume}</div>\n\t\t</div>\n\t\t<Slider value={volume} onchange={(v) => (volume = v)} />\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Step 2 of 0–10 · sm</div>\n\t\t<Slider value={level} min={0} max={10} step={2} size=\"h-sm\" onchange={(v) => (level = v)} />\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Large</div>\n\t\t<Slider value={brightness} size=\"h-bs\" onchange={(v) => (brightness = v)} />\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">Disabled</div>\n\t\t<Slider value={30} disabled />\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- A click or drag on the root sets the value from the track's painted bounds, so the root's hit area is taller than the track.\n- The thumb is a child of the fill, so its position comes from the fill's width percentage and needs no measurement. Its overhang is a negative `right` offset.\n- GPUI does not capture the pointer, so a drag shows a window-sized cover, which ends the drag on release or on a move with no button held.", demo: Slider },
	{ name: 'Switch', category: 'inputs', description: "On/off toggle with a track and thumb, optional label, and three sizes.", docs: "`Switch` is a controlled on/off control. The parent owns `checked` and updates it in `onchange`, which receives the next state. Clicking the track or label, or pressing Space while focused, requests the change.\n\n```svelte\n<script>\n  import Switch from 'gpuix-fractalsvelte-ui/Switch.svelte';\n  let notify = $state(false);\n</script>\n\n<Switch label=\"Notifications\" checked={notify} onchange={(v) => (notify = v)} />\n\n<Switch checked disabled>\n  {#snippet children()}Locked on{/snippet}\n</Switch>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `checked` | `boolean` | `false` |   |\n| `onchange` | `(checked: boolean) => void` | — | Called with the next state when the track or label is clicked, or Space is pressed. |\n| `label` | `string` | `''` | Plain-text label, ignored when `children` is given. |\n| `children` | `Snippet` | — |   |\n| `disabled` | `boolean` | `false` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-surface`, `border-strong`, `radius-full`, `ring`, `switch-h`, `switch-thumb`, `switch-w`, `text-md`, `text-primary`, `text-theme`, `theme-color`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Space | Toggle while focused |\n\nEnter does not toggle. A disabled switch is removed from the tab order (`tabindex -1`).\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Switch from 'gpuix-fractalsvelte-ui/Switch.svelte';\n\n\tlet wifi = $state(true);\n\tlet sync = $state(false);\n\tlet beta = $state(false);\n</script>\n\n<div style=\"display: flex; flex-direction: row; gap: 48px\">\n\t<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t\t<Switch label=\"Small\" checked />\n\t\t<Switch label=\"Medium\" checked={wifi} onchange={(v) => (wifi = v)} />\n\t\t<Switch label=\"Large\" checked />\n\t\t<Switch label=\"Disabled\" disabled />\n\t\t<Switch label=\"Disabled on\" disabled checked />\n\t</div>\n\n\t<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t\t<Switch label=\"Sync across devices\" checked={sync} onchange={(v) => (sync = v)} />\n\t\t<Switch label=\"Join the beta\" checked={beta} onchange={(v) => (beta = v)} />\n\t\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">\n\t\t\tsync {sync ? 'on' : 'off'} · beta {beta ? 'on' : 'off'}\n\t\t</div>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- The focus ring is the track's border colour, since GPUI has no outline.\n- The thumb moves by flipping `justify-content` on the track, so it snaps rather than slides.\n- The root row is clickable, so a click on the label toggles as well as a click on the track.", demo: Switch },
	{ name: 'TextArea', category: 'inputs', description: "Multi-line text field with label, hint or error text, and a height that grows with its content.", docs: "`TextArea` is a controlled multi-line field. The parent owns `value` and updates it in `onchange`, which receives the new text. The field starts at `rows` lines and grows with its text, up to `maxRows` if set.\n\n```svelte\n<script>\n  import TextArea from 'gpuix-fractalsvelte-ui/TextArea.svelte';\n  let notes = $state('');\n</script>\n\n<TextArea label=\"Notes\" placeholder=\"Write something\" hint=\"Shown under the field\" value={notes} onchange={(v) => (notes = v)} />\n\n<TextArea label=\"Bio\" rows={2} maxRows={6} error=\"Too long\" value={bio} onchange={(v) => (bio = v)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `value` | `string` | `''` |   |\n| `onchange` | `(value: string) => void` | — | Called on every edit with the new text. |\n| `placeholder` | `string` | `''` |   |\n| `label` | `string` | `''` | Shown above the field. |\n| `hint` | `string` | `''` | Shown under the field, unless `error` is set. |\n| `error` | `string` | `''` | Shown under the field in the danger colour, in place of `hint`. |\n| `rows` | `number` | `3` | Visible height in lines; the field grows with its text from here. |\n| `maxRows` | `number` | — | Stops growing at this many lines, then scrolls. Unset grows without limit. |\n| `disabled` | `boolean` | `false` | Greys the field and ignores edits. |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` | Text size: fractalstyler's sm, md or lg. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `border-strong`, `danger`, `font-sans`, `radius-lg`, `radius-md`, `radius-sm`, `ring`, `text-primary`, `text-secondary`, `text-sm`\n## Keyboard\n\nNone handled by the component. Enter inserts a line, as in any multi-line field.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport TextArea from 'gpuix-fractalsvelte-ui/TextArea.svelte';\n\tlet notes = $state('');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px; width: 360px\">\n\t<TextArea\n\t\tlabel=\"Notes\"\n\t\tplaceholder=\"Write freely. The field grows with the text.\"\n\t\thint=\"Enter adds a line\"\n\t\tvalue={notes}\n\t\tonchange={(v) => (notes = v)}\n\t\tmaxRows={6}\n\t/>\n\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">{notes.length} characters</div>\n\n\t<TextArea size=\"sm\" rows={2} placeholder=\"Small, two rows\" />\n\t<TextArea size=\"lg\" rows={2} placeholder=\"Large, two rows\" />\n\t<TextArea label=\"Summary\" value=\"This copy is too long for the field.\" error=\"Keep it under 120 characters\" />\n\t<TextArea label=\"Changelog\" value=\"Locked for the release.\" rows={2} disabled />\n</div>\n```\n\n## GPUI notes\n\n- Clicking anywhere in the box focuses the inner textarea, so the padding is part of the hit area.\n- The focus ring is a border colour change, since GPUI has no outline.\n- Line height is fixed in px per size, so `rows` and `maxRows` are exact line counts.\n- A disabled field uses `readOnly` and reduced opacity. The disabled look is not a native disabled state.", demo: TextArea },
	{ name: 'TextInput', category: 'inputs', description: "Single-line text field with label, hint or error text, leading and trailing slots, and three sizes.", docs: "`TextInput` is a controlled single-line field. The parent owns `value` and updates it in `onchange`, which receives the new text. Enter calls `onsubmit` with the current text.\n\n```svelte\n<script>\n  import TextInput from 'gpuix-fractalsvelte-ui/TextInput.svelte';\n  let name = $state('');\n</script>\n\n<TextInput label=\"Name\" placeholder=\"Your name\" hint=\"Shown under the field\" value={name} onchange={(v) => (name = v)} />\n\n<TextInput label=\"Email\" value={email} error=\"Enter a valid email\" onchange={(v) => (email = v)} />\n\n<TextInput size=\"h-xl\" placeholder=\"Search\" onsubmit={(q) => search(q)}>\n  {#snippet leading()}⌕{/snippet}\n</TextInput>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `value` | `string` | `''` |   |\n| `onchange` | `(value: string) => void` | — | Called on every edit with the new text. |\n| `onsubmit` | `(value: string) => void` | — | Called on Enter with the current text. |\n| `placeholder` | `string` | `''` |   |\n| `label` | `string` | `''` | Shown above the field. |\n| `hint` | `string` | `''` | Shown under the field, unless `error` is set. |\n| `error` | `string` | `''` | Shown under the field in the danger colour, in place of `hint`. |\n| `disabled` | `boolean` | `false` | Greys the field and ignores edits. |\n| `size` | `'h-md' \\| 'h-lg' \\| 'h-xl'` | `'h-lg'` | Fractalstyler's height steps for the field. |\n| `leading` | `Snippet` | — | Snippet inside the field, before the text. |\n| `trailing` | `Snippet` | — | Snippet inside the field, after the text. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `border-strong`, `danger`, `font-sans`, `radius-md`, `ring`, `text-primary`, `text-secondary`, `text-sm`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter | Calls `onsubmit` with the current text |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport TextInput from 'gpuix-fractalsvelte-ui/TextInput.svelte';\n\tlet name = $state('');\n\tlet site = $state('');\n\tlet submitted = $state('');\n\tlet query = $state('');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px; width: 360px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: flex-end\">\n\t\t<TextInput size=\"h-md\" placeholder=\"Small\" style=\"flex-grow: 1; flex-basis: 0; min-width: 0\" />\n\t\t<TextInput size=\"h-lg\" placeholder=\"Medium\" style=\"flex-grow: 1; flex-basis: 0; min-width: 0\" />\n\t\t<TextInput size=\"h-xl\" placeholder=\"Large\" style=\"flex-grow: 1; flex-basis: 0; min-width: 0\" />\n\t</div>\n\n\t<TextInput\n\t\tlabel=\"Name\"\n\t\tplaceholder=\"Ada Lovelace\"\n\t\thint=\"Shown on your profile\"\n\t\tvalue={name}\n\t\tonchange={(v) => (name = v)}\n\t\tonsubmit={(v) => (submitted = v)}\n\t/>\n\t<div style=\"color: var(--text-secondary); font-size: var(--text-sm)\">submitted: {submitted || '—'}</div>\n\n\t<TextInput label=\"Website\" placeholder=\"example.com\" value={site} onchange={(v) => (site = v)}>\n\t\t{#snippet leading()}<div>https://</div>{/snippet}\n\t</TextInput>\n\n\t<TextInput\n\t\tplaceholder=\"Search notes\"\n\t\tvalue={query}\n\t\tonchange={(v) => (query = v)}\n\t>\n\t\t{#snippet trailing()}<div style=\"font-size: var(--text-xs)\">esc</div>{/snippet}\n\t</TextInput>\n\n\t<TextInput label=\"Email\" value=\"ada@\" error=\"Enter a valid email address\" />\n\t<TextInput label=\"Organisation\" value=\"Analytical Engine Ltd\" disabled hint=\"Managed by your admin\" />\n</div>\n```\n\n## GPUI notes\n\n- Clicks on the field, including its padding, focus the inner input, so the whole box is the hit area.\n- The focus ring is a border colour change, since GPUI has no outline.\n- A disabled field uses `readOnly` and reduced opacity. The disabled look is not a native disabled state.\n- The inner input is a fixed height per size, and `leading` and `trailing` sit beside it inside the field.", demo: TextInput },
	{ name: 'Box', category: 'layout', description: "Plain flex column with optional padding, background, border and corner radius.", docs: "`Box` is the simplest container: a column with a background, border and radius you choose from a small set of options.\n\n```svelte\n<script>\n  import Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n</script>\n\n<Box bg=\"surface\" padding=\"md\" border radius=\"lg\">\n  Panel content\n</Box>\n<Box bg=\"raised\" radius=\"sm\" padding={6} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `padding` | `'sm' \\| 'md' \\| 'lg' \\| number` | — | Fractalstyler's padding steps, or px. |\n| `bg` | `'surface' \\| 'raised' \\| 'none'` | `'none'` |   |\n| `border` | `boolean` | `false` |   |\n| `radius` | `'none' \\| 'sm' \\| 'md' \\| 'lg'` | `'md'` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n\tconst caption = 'font-size: var(--text-sm); color: var(--text-secondary)';\n\tconst chip = 'padding: 4px 8px; border-radius: var(--radius-sm); background-color: var(--theme-color-sub); font-size: var(--text-sm); color: var(--theme-color)';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style={caption}>Background</div>\n\t\t<div style=\"display: flex; flex-direction: row; gap: 12px\">\n\t\t\t<Box bg=\"none\" padding=\"md\" border style=\"flex-grow: 1\"><div style={caption}>none</div></Box>\n\t\t\t<Box bg=\"surface\" padding=\"md\" border style=\"flex-grow: 1\"><div style={caption}>surface</div></Box>\n\t\t\t<Box bg=\"raised\" padding=\"md\" style=\"flex-grow: 1\"><div style={caption}>raised</div></Box>\n\t\t</div>\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style={caption}>Radius</div>\n\t\t<div style=\"display: flex; flex-direction: row; gap: 12px\">\n\t\t\t{#each ['none', 'sm', 'md', 'lg'] as const as radius}\n\t\t\t\t<Box bg=\"raised\" padding=\"sm\" {radius} border style=\"flex-grow: 1; height: 44px; align-items: center; justify-content: center\">\n\t\t\t\t\t<div style={caption}>{radius}</div>\n\t\t\t\t</Box>\n\t\t\t{/each}\n\t\t</div>\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style={caption}>Padding</div>\n\t\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: start\">\n\t\t\t<Box bg=\"surface\" padding=\"sm\" border><div style={chip}>sm</div></Box>\n\t\t\t<Box bg=\"surface\" padding=\"md\" border><div style={chip}>md</div></Box>\n\t\t\t<Box bg=\"surface\" padding=\"lg\" border><div style={chip}>lg</div></Box>\n\t\t\t<Box bg=\"surface\" padding={20} border><div style={chip}>20px</div></Box>\n\t\t</div>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- `style` is appended after the computed padding, so `style=\"padding: 0\"` overrides the `padding` prop.\n- Padding is written as an inline `padding` in px, not as a class.", demo: Box },
	{ name: 'Card', category: 'layout', description: "Surface with a header, body and footer, optionally clickable as a whole.", docs: "`Card` groups related content under an optional title and description, with slots for header actions and footer buttons. With `clickable` the whole card becomes one action.\n\n```svelte\n<script>\n  import Card from 'gpuix-fractalsvelte-ui/Card.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n</script>\n\n<Card title=\"Project\" description=\"Last edited 2h ago\">\n  Body copy for the card.\n  {#snippet actions()}\n    <Button label=\"Star\" variant=\"ghost\" size=\"h-md\" onclick={star} />\n  {/snippet}\n  {#snippet footer()}\n    <Button label=\"Open\" size=\"h-md\" onclick={open} />\n  {/snippet}\n</Card>\n\n<Card title=\"Recent file\" clickable onclick={openFile}>Click anywhere to open.</Card>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `title` | `string` | `''` |   |\n| `description` | `string` | `''` |   |\n| `actions` | `Snippet` | — | Right side of the header, e.g. icon buttons. |\n| `footer` | `Snippet` | — |   |\n| `padding` | `'sm' \\| 'md' \\| 'lg' \\| number` | `'lg'` | Spacing scale or px, on all four sides. |\n| `clickable` | `boolean` | `false` | Hover highlight, focus ring, and `onclick` on click, Enter or Space. |\n| `onclick` | `(e: GpuixEvent) => void` | — |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `border`, `radius-lg`, `ring`, `text-lg`, `text-primary`, `text-secondary`, `text-sm`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Run `onclick` while focused (only when `clickable`) |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Card from 'gpuix-fractalsvelte-ui/Card.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tlet opened = $state(0);\n\tlet starred = $state(false);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: start\">\n\t\t<div style=\"flex-grow: 1; flex-basis: 0; min-width: 0\">\n\t\t\t<Card title=\"Project Atlas\" description=\"Edited 2 hours ago\">\n\t\t\t\tShared with 4 people. Last build passed on main.\n\t\t\t\t{#snippet footer()}\n\t\t\t\t\t<Button label=\"Cancel\" variant=\"ghost\" size=\"h-md\" />\n\t\t\t\t\t<Button label=\"Open\" size=\"h-md\" />\n\t\t\t\t{/snippet}\n\t\t\t</Card>\n\t\t</div>\n\t\t<div style=\"flex-grow: 1; flex-basis: 0; min-width: 0\">\n\t\t\t<Card title=\"Quarterly report\" description=\"Draft · 12 pages\">\n\t\t\t\t{#snippet actions()}\n\t\t\t\t\t<Button label={starred ? 'Starred' : 'Star'} variant={starred ? 'themed' : 'ghost'} size=\"h-md\" onclick={() => (starred = !starred)} />\n\t\t\t\t{/snippet}\n\t\t\t\tFinance numbers are final. Review the summary before sending.\n\t\t\t</Card>\n\t\t</div>\n\t</div>\n\t<Card title=\"Compact\" description=\"padding sm\" padding=\"sm\">Tight padding.</Card>\n\t<Card title=\"Open a workspace\" description=\"Click the card to open it\" clickable onclick={() => opened++}>\n\t\t<div style=\"color: var(--text-secondary)\">Opened {opened} times.</div>\n\t</Card>\n</div>\n```\n\n## GPUI notes\n\n- A clickable card is focusable (`tabindex` 0). Its focus ring is a border colour change.\n- The `actions` and `footer` rows sit on a near-transparent fill with an `onclick` that does nothing. This stops a button's click from also running the card's `onclick`.\n- Only the `clickable` card gets a `cursor: pointer` and hover background.", demo: Card },
	{ name: 'Divider', category: 'layout', description: "Hairline rule, horizontal or vertical, with an optional centred label.", docs: "`Divider` draws a 1px rule. A horizontal divider can carry a centred label; a vertical one cannot.\n\n```svelte\n<script>\n  import Divider from 'gpuix-fractalsvelte-ui/Divider.svelte';\n</script>\n\n<Divider />\n<Divider label=\"Advanced\" />\n<Divider orientation=\"vertical\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `orientation` | `'horizontal' \\| 'vertical'` | `'horizontal'` |   |\n| `label` | `string` | `''` | Shown centred in a horizontal divider. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`border`, `text-muted`, `text-sm`\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Divider from 'gpuix-fractalsvelte-ui/Divider.svelte';\n\tconst body = 'font-size: var(--text-md); color: var(--text-primary)';\n\tconst muted = 'font-size: var(--text-sm); color: var(--text-secondary)';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px; width: 360px\">\n\t<div style={body}>Profile</div>\n\t<Divider />\n\t<div style={muted}>Name, email and avatar.</div>\n\t<Divider label=\"Advanced\" />\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center; height: 32px\">\n\t\t<div style={body}>Left</div>\n\t\t<Divider orientation=\"vertical\" />\n\t\t<div style={body}>Centre</div>\n\t\t<Divider orientation=\"vertical\" />\n\t\t<div style={body}>Right</div>\n\t</div>\n\t<Divider label=\"Danger zone\" />\n\t<div style={muted}>Deleting a workspace cannot be undone.</div>\n</div>\n```\n\n## GPUI notes\n\n- The rule stretches across the parent's cross axis through `align-self: stretch`, so put it in a flex row or column.\n- A labelled divider is three elements: two `flex-grow` lines around the label.", demo: Divider },
	{ name: 'Grid', category: 'layout', description: "Equal-width column grid with a spacing gap between cells.", docs: "`Grid` lays its children out in a fixed number of equal columns.\n\n```svelte\n<script>\n  import Grid from 'gpuix-fractalsvelte-ui/Grid.svelte';\n  import Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n</script>\n\n<Grid columns={3} gap=\"sm\">\n  {#each items as item}\n    <Box bg=\"raised\" radius=\"sm\" padding=\"md\">{item}</Box>\n  {/each}\n</Grid>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `columns` | `1 \\| 2 \\| 3 \\| 4 \\| 5 \\| 6` | `2` | Number of equal-width columns, 1 to 6 (fractalstyler's grid-N classes). |\n| `gap` | `'xs' \\| 'sm' \\| 'md' \\| 'bs' \\| 'lg' \\| 'xl' \\| number` | `'md'` | Fractalstyler's gap steps, or px. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Grid from 'gpuix-fractalsvelte-ui/Grid.svelte';\n\timport Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n\tconst metrics = [\n\t\t{ label: 'Revenue', value: '$48.2k' },\n\t\t{ label: 'Users', value: '1,284' },\n\t\t{ label: 'Retention', value: '62%' },\n\t\t{ label: 'Latency', value: '84 ms' },\n\t\t{ label: 'Errors', value: '0.2%' },\n\t\t{ label: 'Uptime', value: '99.98%' }\n\t];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 20px\">\n\t<Grid columns={3} gap=\"md\">\n\t\t{#each metrics as m (m.label)}\n\t\t\t<Box bg=\"raised\" padding=\"md\" radius=\"md\">\n\t\t\t\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">{m.label}</div>\n\t\t\t\t<div style=\"font-size: var(--text-xl); font-weight: 600; color: var(--text-primary)\">{m.value}</div>\n\t\t\t</Box>\n\t\t{/each}\n\t</Grid>\n\t<Grid columns={2} gap=\"sm\">\n\t\t{#each ['Inbox', 'Drafts', 'Sent', 'Archive'] as name (name)}\n\t\t\t<Box bg=\"surface\" padding=\"sm\" border radius=\"sm\">\n\t\t\t\t<div style=\"padding: 6px 8px; font-size: var(--text-md); color: var(--text-primary)\">{name}</div>\n\t\t\t</Box>\n\t\t{/each}\n\t</Grid>\n</div>\n```\n\n## GPUI notes\n\n- `columns` is written as a bare number into `grid-template-columns`. GPUI reads that as a count of equal tracks; it is not a standard CSS track list.", demo: Grid },
	{ name: 'ScrollArea', category: 'layout', description: "Vertically scrolling column with a fixed height or a height cap, and a drawn scroll thumb.", docs: "`ScrollArea` wraps its children in a scrolling column. Set `height` for a fixed box or `maxHeight` to shrink to the content up to a cap.\n\n```svelte\n<script>\n  import ScrollArea from 'gpuix-fractalsvelte-ui/ScrollArea.svelte';\n</script>\n\n<ScrollArea maxHeight={160} gap={4}>\n  {#each rows as row}\n    <div>{row}</div>\n  {/each}\n</ScrollArea>\n\n<ScrollArea height={320}>\n  <div>Pinned panel content</div>\n</ScrollArea>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `height` | `number \\| null` | — | Fixed height in px. |\n| `maxHeight` | `number \\| null` | — | Height cap in px; the area shrinks to its content below the cap. |\n| `gap` | `number` | `8` | px between the content's direct children. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\nNone.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport ScrollArea from 'gpuix-fractalsvelte-ui/ScrollArea.svelte';\n\tconst rows = Array.from({ length: 20 }, (_, i) => i + 1);\n\tconst caption = 'font-size: var(--text-sm); color: var(--text-secondary); padding-bottom: 6px';\n\tconst frame = 'width: 200px; padding: 8px; background-color: var(--bg-surface); border-width: 1px; border-color: var(--border); border-radius: var(--radius-md)';\n\tconst line = 'font-size: var(--text-md); color: var(--text-primary)';\n</script>\n\n<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: start\">\n\t<div>\n\t\t<div style={caption}>maxHeight 150</div>\n\t\t<ScrollArea maxHeight={150} gap={4} style={frame}>\n\t\t\t{#each rows as r (r)}<div style=\"height: 22px; {line}\">Message {r}</div>{/each}\n\t\t</ScrollArea>\n\t</div>\n\t<div>\n\t\t<div style={caption}>fixed height 150</div>\n\t\t<ScrollArea height={150} gap={4} style={frame}>\n\t\t\t{#each rows as r (r)}<div style=\"height: 22px; {line}\">Track {r}</div>{/each}\n\t\t</ScrollArea>\n\t</div>\n\t<div>\n\t\t<div style={caption}>short, shrinks to content</div>\n\t\t<ScrollArea maxHeight={150} gap={4} style={frame}>\n\t\t\t<div style=\"height: 22px; {line}\">Only item</div>\n\t\t\t<div style=\"height: 22px; {line}\">Second item</div>\n\t\t</ScrollArea>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- GPUI paints no scrollbars, so the scroll thumb is drawn by the underlying `Scroller` and dragged on an overlay.\n- The thumb colours are translucent neutral greys set with `set_css_vars`. Those variables are global, so they apply to every scroll column in the window, not just this one.\n- `height` and `maxHeight` are written as inline px. Pass both and `height` is applied first, so `maxHeight` only caps it.", demo: ScrollArea },
	{ name: 'Spacer', category: 'layout', description: "Flexible empty box that takes up the free space in a row or column.", docs: "`Spacer` grows to fill the leftover space in its flex parent, pushing siblings apart.\n\n```svelte\n<script>\n  import Spacer from 'gpuix-fractalsvelte-ui/Spacer.svelte';\n  import Stack from 'gpuix-fractalsvelte-ui/Stack.svelte';\n</script>\n\n<Stack direction=\"row\" align=\"center\">\n  <span>Title</span>\n  <Spacer />\n  <span>Actions</span>\n</Stack>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\nNone.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Spacer from 'gpuix-fractalsvelte-ui/Spacer.svelte';\n\timport Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tconst title = 'font-size: var(--text-md); font-weight: 600; color: var(--text-primary)';\n\tconst muted = 'font-size: var(--text-sm); color: var(--text-secondary)';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<Box bg=\"surface\" border radius=\"md\" padding=\"sm\" style=\"flex-direction: row; gap: 8px; align-items: center\">\n\t\t<div style=\"padding: 0 6px; {title}\">Atlas</div>\n\t\t<Spacer />\n\t\t<Button label=\"Share\" variant=\"ghost\" size=\"h-md\" />\n\t\t<Button label=\"Publish\" size=\"h-md\" />\n\t</Box>\n\t<Box bg=\"surface\" border radius=\"md\" padding=\"md\" style=\"height: 200px; gap: 8px\">\n\t\t<div style={title}>Invoice #1042</div>\n\t\t<div style={muted}>Issued 3 June · Due 17 June</div>\n\t\t<Spacer />\n\t\t<div style={muted}>Total due</div>\n\t\t<div style=\"font-size: var(--text-2xl); font-weight: 600; color: var(--text-primary)\">$2,480.00</div>\n\t\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t\t<Spacer />\n\t\t\t<Button label=\"Pay now\" size=\"h-md\" />\n\t\t</div>\n\t</Box>\n</div>\n```\n\n## GPUI notes\n\n- Sizing is `flex-grow: 1` only. It works inside a flex row or column, and does nothing in a parent without flex.\n- Set a size through `style` to keep a minimum gap, since the spacer itself has no minimum.", demo: Spacer },
	{ name: 'SplitPane', category: 'layout', description: "Two panes divided by a draggable, keyboard-nudgeable grip, side by side or stacked.", docs: "`SplitPane` puts `first` and `second` either side by side (`row`) or stacked (`column`), with a grip between them. Drag the grip, or focus it and press the arrow keys, to resize the first pane.\n\n```svelte\n<script>\n  import SplitPane from 'gpuix-fractalsvelte-ui/SplitPane.svelte';\n  let width = $state(240);\n</script>\n\n<div style=\"height: 400px; display: flex; flex-direction: column\">\n  <SplitPane initial={240} minFirst={120} minSecond={120} onresize={(s) => (width = s)}>\n    {#snippet first()}<div>Sidebar</div>{/snippet}\n    {#snippet second()}<div>Editor</div>{/snippet}\n  </SplitPane>\n</div>\n\n<SplitPane direction=\"column\" initial={160}>\n  {#snippet first()}<div>Top</div>{/snippet}\n  {#snippet second()}<div>Bottom</div>{/snippet}\n</SplitPane>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `first` | `Snippet` | — |   |\n| `second` | `Snippet` | — |   |\n| `direction` | `'row' \\| 'column'` | `'row'` | `row` puts the panes side by side; `column` stacks them. |\n| `initial` | `number` | `240` | First pane's size in px at mount. |\n| `minFirst` | `number` | `80` |   |\n| `minSecond` | `number` | `80` |   |\n| `onresize` | `(size: number) => void` | — | Called with the first pane's size in px while it is dragged or nudged with the arrow keys. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`border`, `ring`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Left / Right (`row`) | Move the divider 10 px while the grip is focused |\n| Up / Down (`column`) | Move the divider 10 px while the grip is focused |\n\nThe grip is focusable (Tab), and its line turns the ring colour while focused or dragged.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport SplitPane from 'gpuix-fractalsvelte-ui/SplitPane.svelte';\n\tconst files = ['index.ts', 'Button.svelte', 'Modal.svelte', 'tokens.ts', 'README.md'];\n\tconst caption = 'font-size: var(--text-sm); color: var(--text-secondary)';\n\tconst pane = 'display: flex; flex-direction: column; flex-grow: 1; background-color: var(--bg-surface); padding: 10px 12px; gap: 4px';\n\tlet width = $state(0);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: column; height: 200px; border-width: 1px; border-color: var(--border); border-radius: var(--radius-md)\">\n\t\t<SplitPane initial={180} minFirst={120} minSecond={160} onresize={(s) => (width = s)}>\n\t\t\t{#snippet first()}\n\t\t\t\t<div style=\"{pane}; background-color: var(--bg-raised)\">\n\t\t\t\t\t<div style=\"font-size: var(--text-sm); font-weight: 600; color: var(--text-secondary); padding-bottom: 4px\">FILES</div>\n\t\t\t\t\t{#each files as f (f)}<div style=\"font-size: var(--text-md); color: var(--text-primary)\">{f}</div>{/each}\n\t\t\t\t</div>\n\t\t\t{/snippet}\n\t\t\t{#snippet second()}\n\t\t\t\t<div style={pane}>\n\t\t\t\t\t<div style=\"font-size: var(--text-lg); font-weight: 600; color: var(--text-primary)\">Button.svelte</div>\n\t\t\t\t\t<div style={caption}>Drag the divider, or focus it and use the arrow keys.</div>\n\t\t\t\t</div>\n\t\t\t{/snippet}\n\t\t</SplitPane>\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; height: 150px; border-width: 1px; border-color: var(--border); border-radius: var(--radius-md)\">\n\t\t<SplitPane direction=\"column\" initial={70} minFirst={50} minSecond={50}>\n\t\t\t{#snippet first()}\n\t\t\t\t<div style=\"{pane}; background-color: var(--bg-raised)\"><div style=\"font-size: var(--text-md); color: var(--text-primary)\">Input</div></div>\n\t\t\t{/snippet}\n\t\t\t{#snippet second()}\n\t\t\t\t<div style={pane}><div style=\"font-size: var(--text-md); color: var(--text-primary)\">Output</div></div>\n\t\t\t{/snippet}\n\t\t</SplitPane>\n\t</div>\n\t<div style={caption}>Top pane width: {width || 180}px</div>\n</div>\n```\n\n## GPUI notes\n\n- GPUI does not capture the pointer. While dragging, an overlay covers the whole split so moves keep arriving, and a move with no button held ends the drag (the release landed elsewhere).\n- Sizes are clamped to the split's painted bounds, which GPUI reports after mount. Before that, only `minFirst` applies.\n- `initial` is read once, at mount. To set the size from outside, keep it in state and track it through `onresize`.", demo: SplitPane },
	{ name: 'Stack', category: 'layout', description: "Flex row or column with spacing, alignment, justification and optional wrapping.", docs: "`Stack` lays out its children in a flex row or column with a shared gap and padding. Use it instead of hand-writing flex styles.\n\n```svelte\n<script>\n  import Stack from 'gpuix-fractalsvelte-ui/Stack.svelte';\n</script>\n\n<Stack gap=\"sm\" padding=\"md\">\n  <div>First</div>\n  <div>Second</div>\n</Stack>\n\n<Stack direction=\"row\" align=\"center\" justify=\"between\" gap={12}>\n  <span>Label</span>\n  <span>Value</span>\n</Stack>\n\n<Stack direction=\"row\" wrap gap=\"md\" style=\"width: 240px\">\n  <div>Tag</div>\n  <div>Tag</div>\n</Stack>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — |   |\n| `direction` | `'row' \\| 'column'` | `'column'` |   |\n| `gap` | `'xs' \\| 'sm' \\| 'md' \\| 'bs' \\| 'lg' \\| 'xl' \\| number` | `'sm'` | Fractalstyler's gap steps, or px. |\n| `align` | `'start' \\| 'center' \\| 'end' \\| 'stretch'` | `'stretch'` |   |\n| `justify` | `'start' \\| 'center' \\| 'end' \\| 'between' \\| 'around'` | `'start'` |   |\n| `wrap` | `boolean` | `false` |   |\n| `padding` | `'sm' \\| 'md' \\| 'lg' \\| number` | — | Fractalstyler's padding steps, or px, on all four sides. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\nNone.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Stack from 'gpuix-fractalsvelte-ui/Stack.svelte';\n\timport Box from 'gpuix-fractalsvelte-ui/Box.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tconst chip = 'font-size: var(--text-sm); color: var(--text-primary)';\n\tconst caption = 'font-size: var(--text-sm); color: var(--text-secondary)';\n\tconst tags = ['Design', 'Svelte', 'GPUI', 'Rust', 'Motion', 'Tokens', 'Docs'];\n\tlet justify = $state<'start' | 'center' | 'between'>('between');\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 18px\">\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style={caption}>Row, gap md, align center</div>\n\t\t<Stack direction=\"row\" gap=\"md\" align=\"center\">\n\t\t\t{#each tags.slice(0, 3) as t (t)}\n\t\t\t\t<Box bg=\"raised\" radius=\"sm\" padding={6}><div style={chip}>{t}</div></Box>\n\t\t\t{/each}\n\t\t</Stack>\n\t</div>\n\t<div style=\"display: flex; flex-direction: column; gap: 8px\">\n\t\t<div style={caption}>Row, justify {justify} (click to cycle)</div>\n\t\t<Stack direction=\"row\" justify={justify} align=\"center\" gap=\"sm\" style=\"padding: 10px; background-color: var(--bg-surface); border-width: 1px; border-color: var(--border); border-radius: var(--radius-md)\">\n\t\t\t<div style=\"font-size: var(--text-md); font-weight: 600; color: var(--text-primary)\">Toolbar</div>\n\t\t\t<Button label=\"Cycle\" variant=\"outline\" size=\"h-md\" onclick={() => (justify = justify === 'between' ? 'center' : justify === 'center' ? 'start' : 'between')} />\n\t\t</Stack>\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 24px; align-items: start\">\n\t\t<div style=\"display: flex; flex-direction: column; gap: 8px; flex-grow: 1\">\n\t\t\t<div style={caption}>Column, gap sm</div>\n\t\t\t<Stack direction=\"column\" gap=\"sm\">\n\t\t\t\t<Box bg=\"raised\" radius=\"sm\" padding=\"sm\"><div style={chip}>Step one</div></Box>\n\t\t\t\t<Box bg=\"raised\" radius=\"sm\" padding=\"sm\"><div style={chip}>Step two</div></Box>\n\t\t\t\t<Box bg=\"raised\" radius=\"sm\" padding=\"sm\"><div style={chip}>Step three</div></Box>\n\t\t\t</Stack>\n\t\t</div>\n\t\t<div style=\"display: flex; flex-direction: column; gap: 8px; width: 200px\">\n\t\t\t<div style={caption}>Wrap in 200px</div>\n\t\t\t<Stack direction=\"row\" wrap gap=\"sm\">\n\t\t\t\t{#each tags as t (t)}\n\t\t\t\t\t<Box bg=\"raised\" radius=\"sm\" padding={6}><div style={chip}>{t}</div></Box>\n\t\t\t\t{/each}\n\t\t\t</Stack>\n\t\t</div>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- Gap and padding are written as inline px, so `style` can override them by appearing later in the same declaration list.\n- `align` and `justify` map to class names (`al-*`, `jc-*`) rather than inline styles.", demo: Stack },
	{ name: 'Breadcrumbs', category: 'navigation', description: "Trail of ancestor pages, with the last item marked as the current page.", docs: "`Breadcrumbs` shows where you are. Items with an `onclick` are links; the last item is the current page and is never a link.\n\n```svelte\n<script>\n  import Breadcrumbs from 'gpuix-fractalsvelte-ui/Breadcrumbs.svelte';\n</script>\n\n<Breadcrumbs\n  items={[\n    { label: 'Home', onclick: goHome },\n    { label: 'Projects', onclick: goProjects },\n    { label: 'Fractal' }\n  ]}\n/>\n<Breadcrumbs size=\"sm\" separator=\"›\" items={[{ label: 'Settings' }, { label: 'Billing' }]} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `items` | `{ label: string; onclick?: () => void }[]` | — | Ancestors with an `onclick` are links; the last item is the current page. |\n| `separator` | `string` | `'/'` |   |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` | Fractalstyler's text sizes. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `radius-sm`, `ring`, `text-lg`, `text-md`, `text-muted`, `text-primary`, `text-secondary`, `text-sm`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Tab | Moves between links |\n| Enter, Space | Runs the focused link's `onclick` |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Breadcrumbs from 'gpuix-fractalsvelte-ui/Breadcrumbs.svelte';\n\tlet visited = $state('none');\n\tconst go = (name: string) => () => (visited = name);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px; align-items: start\">\n\t<Breadcrumbs\n\t\titems={[\n\t\t\t{ label: 'Workspace', onclick: go('Workspace') },\n\t\t\t{ label: 'Projects', onclick: go('Projects') },\n\t\t\t{ label: 'Fractal UI' }\n\t\t]}\n\t/>\n\t<Breadcrumbs\n\t\tsize=\"sm\"\n\t\tseparator=\"›\"\n\t\titems={[{ label: 'Settings', onclick: go('Settings') }, { label: 'Keyboard' }]}\n\t/>\n\t<Breadcrumbs\n\t\tsize=\"lg\"\n\t\tseparator=\"→\"\n\t\titems={[{ label: 'Docs', onclick: go('Docs') }, { label: 'Components' }]}\n\t/>\n\t<div style=\"color: var(--text-secondary)\">last visited: {visited}</div>\n</div>\n```\n\n## GPUI notes\n\n- Links are focusable only when they have an `onclick`, so the current page is skipped by Tab.\n- Don't name a class `link`: this renderer treats it as a reserved name and paints the text green.", demo: Breadcrumbs },
	{ name: 'Menu', category: 'navigation', description: "Dropdown of actions anchored to a trigger, with shortcuts, variants, disabled items and separators.", docs: "`Menu` opens a panel of actions beside its trigger, using `Popover`. The parent owns `open` and handles `onopenchange`. Selecting an item runs its `onselect` and closes the menu.\n\n```svelte\n<script>\n  import Menu from 'gpuix-fractalsvelte-ui/Menu.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n  let open = $state(false);\n</script>\n\n<Menu\n  {open}\n  onopenchange={(o) => (open = o)}\n  items={[\n    { label: 'Rename', shortcut: '⌘R', onselect: rename },\n    { label: 'Duplicate', shortcut: '⌘D', onselect: duplicate },\n    { separator: true },\n    { label: 'Archive', disabled: true, onselect: archive },\n    { label: 'Delete', variant: 'danger', onselect: remove }\n  ]}\n>\n  {#snippet trigger()}<Button label=\"Actions\" size=\"h-sm\" />{/snippet}\n</Menu>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `items` | `Entry[]` | — |   |\n| `trigger` | `Snippet` | — | The trigger's content. Keep it free of its own `onclick`, or the trigger's click never reaches the menu. |\n| `open` | `boolean` | `false` |   |\n| `onopenchange` | `(open: boolean) => void` | — |   |\n| `side` | `'top' \\| 'bottom'` | `'bottom'` |   |\n| `align` | `'start' \\| 'center' \\| 'end'` | `'start'` |   |\n| `style` | `string \\| null` | — | Inline CSS for the panel, e.g. `min-width: 220px`. |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `border`, `danger`, `danger-soft`, `font-mono`, `info`, `radius-md`, `radius-sm`, `ring`, `success`, `text-md`, `text-muted`, `text-primary`, `text-xs`, `theme-color`, `warning`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space, Down | On the focused trigger: open the menu, with the first item highlighted |\n| Down, Up | Move the highlight; skips separators and disabled items, and wraps |\n| Enter | Pick the highlighted item |\n| Escape | Close without picking |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Menu from 'gpuix-fractalsvelte-ui/Menu.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tlet open = $state(false);\n\tlet picked = $state('nothing');\n\tconst pick = (name: string) => () => (picked = name);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 24px; align-items: start\">\n\t\t<Menu\n\t\t\t{open}\n\t\t\tonopenchange={(o) => (open = o)}\n\t\t\tstyle=\"min-width: 220px\"\n\t\t\titems={[\n\t\t\t\t{ label: 'Rename', shortcut: '⌘R', onselect: pick('Rename') },\n\t\t\t\t{ label: 'Duplicate', shortcut: '⌘D', onselect: pick('Duplicate') },\n\t\t\t\t{ label: 'Share…', onselect: pick('Share') },\n\t\t\t\t{ separator: true },\n\t\t\t\t{ label: 'Archive', disabled: true, onselect: pick('Archive') },\n\t\t\t\t{ label: 'Delete', shortcut: '⌫', variant: 'danger', onselect: pick('Delete') }\n\t\t\t]}\n\t\t>\n\t\t\t{#snippet trigger()}<Button label=\"Actions\" variant=\"outline\" />{/snippet}\n\t\t</Menu>\n\t\t<Menu side=\"top\" items={[{ label: 'Above the trigger', onselect: pick('Above') }]}>\n\t\t\t{#snippet trigger()}<Button label=\"Open upward\" variant=\"outline\" />{/snippet}\n\t\t</Menu>\n\t\t<div style=\"color: var(--text-secondary); padding-top: 8px\">picked: {picked}</div>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- The trigger must not carry its own `onclick`; a child's click handler would stop the trigger's click from reaching the menu. A `Button` with no `onclick` works.\n- The panel is styled inline, because the `Popover` panel otherwise reads its colours from `--popover-*` variables that this library does not set.\n- Highlight follows the pointer as well as the arrow keys.", demo: Menu },
	{ name: 'NavList', category: 'navigation', description: "Vertical sidebar list with section headings, optional icons and badges.", docs: "`NavList` is a sidebar of sections and items. The parent owns `value` and handles `onchange`. An item can carry an `icon` snippet and a short `badge` text.\n\n```svelte\n<script>\n  import NavList from 'gpuix-fractalsvelte-ui/NavList.svelte';\n  let value = $state('inbox');\n  const sections = [\n    { title: 'Mail', items: [\n      { id: 'inbox', label: 'Inbox', badge: '12' },\n      { id: 'drafts', label: 'Drafts' }\n    ] },\n    { title: 'Account', items: [\n      { id: 'billing', label: 'Billing', disabled: true }\n    ] }\n  ];\n</script>\n\n<NavList {sections} {value} onchange={(id) => (value = id)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `sections` | `{ title?: string; items: Item[] }[]` | — |   |\n| `value` | `string` | — | The active item's id. |\n| `onchange` | `(id: string) => void` | — |   |\n| `size` | `'h-md' \\| 'h-lg' \\| 'h-xl'` | `'h-lg'` | Fractalstyler's height steps for each item. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `radius-full`, `radius-md`, `ring`, `text-muted`, `text-primary`, `text-secondary`, `text-xs`, `theme-color`, `theme-color-sub`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Up, Down | Select and focus the previous or next enabled item; wraps at the ends |\n| Enter, Space | Select the focused item |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport NavList from 'gpuix-fractalsvelte-ui/NavList.svelte';\n\tlet value = $state('inbox');\n\tconst sections = [\n\t\t{\n\t\t\ttitle: 'Mail',\n\t\t\titems: [\n\t\t\t\t{ id: 'inbox', label: 'Inbox', badge: '12', icon: inbox },\n\t\t\t\t{ id: 'drafts', label: 'Drafts', badge: '2' },\n\t\t\t\t{ id: 'starred', label: 'Starred' }\n\t\t\t]\n\t\t},\n\t\t{\n\t\t\ttitle: 'Account',\n\t\t\titems: [\n\t\t\t\t{ id: 'general', label: 'General', icon: gear },\n\t\t\t\t{ id: 'billing', label: 'Billing', disabled: true }\n\t\t\t]\n\t\t}\n\t];\n</script>\n\n{#snippet inbox()}<text>✉</text>{/snippet}\n{#snippet gear()}<text>⚙</text>{/snippet}\n\n<div style=\"display: flex; flex-direction: row; gap: 32px\">\n\t<div style=\"width: 220px\"><NavList {sections} {value} onchange={(id) => (value = id)} /></div>\n\t<div style=\"width: 180px\"><NavList {sections} value=\"general\" size=\"h-md\" /></div>\n</div>\n```\n\n## GPUI notes\n\n- Icon snippets inherit the row's colour, so a `<text>` glyph follows the active accent.\n- Like `Tabs`, focus moves with `focus_element`, which only a live window honours. Headless tests call `focus()` for the same step.", demo: NavList },
	{ name: 'Pagination', category: 'navigation', description: "Page controls with previous and next buttons and a windowed run of page numbers around the current page.", docs: "`Pagination` shows page numbers around the current page, with ellipses for the gaps. The parent owns `page` and handles `onchange`.\n\n```svelte\n<script>\n  import Pagination from 'gpuix-fractalsvelte-ui/Pagination.svelte';\n  let page = $state(1);\n</script>\n\n<Pagination {page} total={24} onchange={(p) => (page = p)} />\n<Pagination {page} total={5} siblings={2} size=\"h-sm\" onchange={(p) => (page = p)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `page` | `number` | — | The current page, from 1. |\n| `total` | `number` | — |   |\n| `siblings` | `number` | `1` | Pages shown either side of the current one. |\n| `onchange` | `(page: number) => void` | — |   |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-md'` | Fractalstyler's height steps for the buttons. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`text-muted`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Tab | Moves between the controls |\n| Enter, Space | Goes to the focused page, or to previous or next |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Pagination from 'gpuix-fractalsvelte-ui/Pagination.svelte';\n\tlet page = $state(1);\n\tlet wide = $state(7);\n\tlet small = $state(2);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px; align-items: start\">\n\t<Pagination {page} total={24} onchange={(p) => (page = p)} />\n\t<Pagination page={wide} total={24} siblings={2} onchange={(p) => (wide = p)} />\n\t<Pagination page={small} total={5} size=\"h-sm\" onchange={(p) => (small = p)} />\n\t<Pagination page={3} total={3} size=\"h-lg\" />\n\t<div style=\"color: var(--text-secondary)\">page {page}</div>\n</div>\n```\n\n## GPUI notes\n\n- Built from `Button`, so the controls share its focus ring and disabled behaviour.\n- Page buttons get a minimum width matching the height, so one-digit and two-digit pages line up.", demo: Pagination },
	{ name: 'Tabs', category: 'navigation', description: "Switch between sibling views with an underline or a segmented pill control.", docs: "`Tabs` shows one panel at a time. The parent owns `value` and handles `onchange`; the optional `children` snippet receives the active id and renders the panel below.\n\n```svelte\n<script>\n  import Tabs from 'gpuix-fractalsvelte-ui/Tabs.svelte';\n  let value = $state('overview');\n  const items = [\n    { id: 'overview', label: 'Overview' },\n    { id: 'activity', label: 'Activity' },\n    { id: 'billing', label: 'Billing', disabled: true }\n  ];\n</script>\n\n<Tabs {items} {value} onchange={(id) => (value = id)}>\n  {#snippet children(id)}<div>Showing {id}</div>{/snippet}\n</Tabs>\n<Tabs {items} {value} variant=\"pill\" size=\"h-md\" onchange={(id) => (value = id)} />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `items` | `{ id: string; label: string; disabled?: boolean }[]` | — |   |\n| `value` | `string` | — | The active tab's id. |\n| `onchange` | `(id: string) => void` | — |   |\n| `variant` | `'line' \\| 'pill'` | `'line'` | `line` underlines the active tab; `pill` is a segmented control. |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg' \\| 'h-xl'` | `'h-bs'` | Fractalstyler's height steps for each tab. |\n| `children` | `Snippet<[string]>` | — | The panel under the tabs, given the active id. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-surface`, `border`, `radius-md`, `ring`, `text-primary`, `text-secondary`, `theme-color`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Left, Right | Select and focus the previous or next enabled tab; wraps at the ends |\n| Enter, Space | Select the focused tab |\n\nOnly the active tab is in the tab order, so Tab moves past the whole row.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Tabs from 'gpuix-fractalsvelte-ui/Tabs.svelte';\n\tlet line = $state('overview');\n\tlet pill = $state('day');\n\tlet small = $state('code');\n\tconst items = [\n\t\t{ id: 'overview', label: 'Overview' },\n\t\t{ id: 'activity', label: 'Activity' },\n\t\t{ id: 'billing', label: 'Billing', disabled: true },\n\t\t{ id: 'settings', label: 'Settings' }\n\t];\n\tconst periods = [\n\t\t{ id: 'day', label: 'Day' },\n\t\t{ id: 'week', label: 'Week' },\n\t\t{ id: 'month', label: 'Month' }\n\t];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 24px; width: 420px\">\n\t<Tabs {items} value={line} onchange={(id) => (line = id)}>\n\t\t{#snippet children(id)}<div style=\"color: var(--text-secondary)\">Showing {id}.</div>{/snippet}\n\t</Tabs>\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center\">\n\t\t<Tabs items={periods} value={pill} variant=\"pill\" onchange={(id) => (pill = id)} />\n\t\t<Tabs items={periods} value={small} variant=\"pill\" size=\"h-md\" onchange={(id) => (small = id)} />\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- The focus ring is a border colour change, since GPUI has no outline.\n- The line underline is a 2 px child bar, because GPUI cannot set a single border side's colour.\n- Disabled tabs drop their hover rule rather than overriding it, using the `rest` class.", demo: Tabs },
	{ name: 'ContextMenu', category: 'overlays', description: "Wraps a region and opens a menu of actions on right click or ctrl+click.", docs: "`ContextMenu` wraps any region. A right click, or ctrl+click on macOS, opens a menu at the pointer. The menu is drawn through `Portal` and closes on choice, scrim click, right click or Escape.\n\n```svelte\n<script>\n  import ContextMenu, { type MenuEntry } from 'gpuix-fractalsvelte-ui/ContextMenu.svelte';\n\n  const items: MenuEntry[] = [\n    { label: 'Copy', onselect: copy },\n    { label: 'Paste', onselect: paste },\n    { separator: true },\n    { label: 'Delete', danger: true, onselect: remove }\n  ];\n</script>\n\n<ContextMenu {items}>\n  <div>Right-click here</div>\n</ContextMenu>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `items` | `MenuEntry[]` | — |   |\n| `children` | `Snippet` | — | The region that opens the menu on a right click, or ctrl+click on macOS. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `bg-sunken`, `border`, `danger`, `radius-md`, `radius-sm`, `text-md`, `text-muted`, `text-primary`\n## Keyboard\n\nHandled while the menu is open. Keys are read window-wide, so focus does not matter.\n\n| Key | Action |\n| --- | --- |\n| Down, Up | Move the highlight, skipping separators and disabled items |\n| Enter | Choose the highlighted item |\n| Escape | Close without choosing |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport ContextMenu, { type MenuEntry } from 'gpuix-fractalsvelte-ui/ContextMenu.svelte';\n\tlet last = $state('none');\n\tconst pick = (name: string) => () => (last = name);\n\tconst items: MenuEntry[] = [\n\t\t{ label: 'Cut', onselect: pick('Cut') },\n\t\t{ label: 'Copy', onselect: pick('Copy') },\n\t\t{ label: 'Paste', onselect: pick('Paste') },\n\t\t{ separator: true },\n\t\t{ label: 'Rename', onselect: pick('Rename') },\n\t\t{ label: 'Duplicate', disabled: true, onselect: pick('Duplicate') },\n\t\t{ separator: true },\n\t\t{ label: 'Delete', danger: true, onselect: pick('Delete') }\n\t];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<ContextMenu\n\t\t{items}\n\t\tstyle=\"height: 150px; align-items: center; justify-content: center; background-color: var(--bg-surface); border-width: 1px; border-color: var(--border); border-radius: var(--radius-lg)\"\n\t>\n\t\t<div style=\"font-size: var(--text-md); color: var(--text-primary)\">Right-click anywhere in this panel</div>\n\t</ContextMenu>\n\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">last action: {last}</div>\n</div>\n```\n\n## GPUI notes\n\n- The menu's position is read once, when it opens, from the window size, and clamped so it stays inside the window. The window is assumed not to resize while it is open.\n- Right click arrives as `onauxclick` and is checked with `e.isRightClick`. ctrl+click arrives as an ordinary `onclick` with `e.modifiers.ctrl`.\n- The region has `hitbox=\"self\"`, so clicks on its children still open the menu.\n- The menu has its own empty `onclick`, so clicks on it don't reach the scrim and close it.", demo: ContextMenu },
	{ name: 'Drawer', category: 'overlays', description: "Panel that slides in from the left, right or bottom over a scrim, with title, body and footer.", docs: "`Drawer` renders through `Portal` and slides its panel in from an edge. The parent owns `open`; the drawer only asks to close through `onclose`.\n\n```svelte\n<script>\n  import Drawer from 'gpuix-fractalsvelte-ui/Drawer.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n  let open = $state(false);\n</script>\n\n<Button label=\"Settings\" onclick={() => (open = true)} />\n<Drawer {open} side=\"right\" size=\"sm\" title=\"Settings\" onclose={() => (open = false)}>\n  Settings body.\n  {#snippet footer()}\n    <Button label=\"Apply\" onclick={apply} />\n  {/snippet}\n</Drawer>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `open` | `boolean` | `false` |   |\n| `onclose` | `() => void` | — | Called on scrim click, Escape or the ✕ button; the parent sets `open = false`. |\n| `side` | `'left' \\| 'right' \\| 'bottom'` | `'right'` | The edge the panel slides in from. |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` | Width for `left` and `right`, height for `bottom`. |\n| `title` | `string` | `''` |   |\n| `dismissable` | `boolean` | `true` | `false` ignores scrim clicks and Escape. |\n| `children` | `Snippet` | — |   |\n| `footer` | `Snippet` | — | Action row, right-aligned. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-extra`, `bg-raised`, `bg-sunken`, `bg-surface`, `border`, `radius-sm`, `text-lg`, `text-primary`, `text-secondary`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Escape | Close, while open and `dismissable` |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\timport Drawer from 'gpuix-fractalsvelte-ui/Drawer.svelte';\n\ttype Side = 'left' | 'right' | 'bottom';\n\tlet open = $state(false);\n\tlet locked = $state(false);\n\tlet side = $state<Side>('right');\n\tlet size = $state<'sm' | 'md' | 'lg'>('sm');\n\tlet applied = $state(0);\n\tconst show = (s: Side) => {\n\t\tside = s;\n\t\topen = true;\n\t};\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"Left\" variant=\"outline\" onclick={() => show('left')} />\n\t\t<Button label=\"Right\" onclick={() => show('right')} />\n\t\t<Button label=\"Bottom\" variant=\"outline\" onclick={() => show('bottom')} />\n\t\t<Button label=\"Locked\" variant=\"outline\" onclick={() => (locked = true)} />\n\t\t<div style=\"flex-grow: 1\"></div>\n\t\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">applied {applied}×</div>\n\t</div>\n\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">Size for left and right drawers: sm, md, lg. Escape or a scrim click closes.</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px\">\n\t\t{#each ['sm', 'md', 'lg'] as const as s}\n\t\t\t<Button label={s} size=\"h-md\" variant={size === s ? 'primary' : 'outline'} onclick={() => (size = s)} />\n\t\t{/each}\n\t</div>\n\t<Drawer open={locked} side=\"left\" size=\"sm\" title=\"Locked\" dismissable={false} onclose={() => (locked = false)}>\n\t\tEscape and the scrim do nothing here.\n\t\t{#snippet footer()}<Button label=\"Close\" onclick={() => (locked = false)} />{/snippet}\n\t</Drawer>\n\t<Drawer {open} {side} {size} title=\"Settings\" onclose={() => (open = false)}>\n\t\t<div style=\"font-size: var(--text-md); color: var(--text-primary)\">Workspace</div>\n\t\t<div>Choose the defaults used for new projects, including the theme, font size and autosave interval.</div>\n\t\t<div>Changes apply to every window once you press Apply.</div>\n\t\t{#snippet footer()}\n\t\t\t<Button label=\"Cancel\" variant=\"ghost\" onclick={() => (open = false)} />\n\t\t\t<Button label=\"Apply\" onclick={() => { applied++; open = false; }} />\n\t\t{/snippet}\n\t</Drawer>\n</div>\n```\n\n## GPUI notes\n\n- The Escape listener is registered only while the drawer is open and dismissable.\n- The scrim fades in and the panel slides in through `motion`. Durations are 0.2 s.\n- The panel has an empty `onclick`, so clicks inside it don't reach the scrim.\n- `style` is appended after the size's width or height, so it can override them.", demo: Drawer },
	{ name: 'Modal', category: 'overlays', description: "Centred dialog over a scrim, with title, body and footer actions.", docs: "`Modal` renders through `Portal`, so it paints over everything wherever you place it. The parent owns `open`; the modal only asks to close through `onclose`.\n\n```svelte\n<script>\n  import Modal from 'gpuix-fractalsvelte-ui/Modal.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n  let open = $state(false);\n</script>\n\n<Button label=\"Delete\" variant=\"danger\" onclick={() => (open = true)} />\n<Modal {open} onclose={() => (open = false)} title=\"Delete file?\" size=\"sm\">\n  This cannot be undone.\n  {#snippet footer()}\n    <Button label=\"Cancel\" variant=\"ghost\" onclick={() => (open = false)} />\n    <Button label=\"Delete\" variant=\"danger\" onclick={remove} />\n  {/snippet}\n</Modal>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `open` | `boolean` | `false` |   |\n| `onclose` | `() => void` | — | Called on scrim click, Escape or the close button; the parent sets `open = false`. |\n| `title` | `string` | `''` |   |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` | Dialog width: sm 360, md 480, lg 640. |\n| `dismissable` | `boolean` | `true` | `false` ignores scrim clicks and Escape. |\n| `children` | `Snippet` | — |   |\n| `footer` | `Snippet` | — | Action row, right-aligned. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-extra`, `bg-raised`, `bg-sunken`, `bg-surface`, `border`, `radius-lg`, `radius-sm`, `text-lg`, `text-primary`, `text-secondary`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Escape | Close (when `dismissable`) |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\timport Modal from 'gpuix-fractalsvelte-ui/Modal.svelte';\n\tlet open = $state(false);\n\tlet small = $state(false);\n</script>\n\n<div style=\"display: flex; flex-direction: row\">\n\t<Button label=\"Open modal\" onclick={() => (open = true)} />\n\t<Button label=\"Small, not dismissable\" variant=\"outline\" onclick={() => (small = true)} />\n</div>\n<Modal {open} onclose={() => (open = false)} title=\"Publish changes?\">\n\tYour edits will be visible to everyone with access.\n\t{#snippet footer()}\n\t\t<Button label=\"Cancel\" variant=\"ghost\" onclick={() => (open = false)} />\n\t\t<Button label=\"Publish\" onclick={() => (open = false)} />\n\t{/snippet}\n</Modal>\n<Modal open={small} onclose={() => (small = false)} title=\"Locked\" size=\"sm\" dismissable={false}>\n\tEscape and the scrim do nothing here.\n\t{#snippet footer()}\n\t\t<Button label=\"Close\" onclick={() => (small = false)} />\n\t{/snippet}\n</Modal>\n```\n\n## GPUI notes\n\n- A dialog needs an `onclick` of its own so clicks inside it don't reach the scrim; the component handles this.\n- There is no enter/exit animation yet.", demo: Modal },
	{ name: 'Popover', category: 'overlays', description: "Floating panel anchored to a trigger, or to window coordinates, that closes on outside press or Escape.", docs: "`Popover` shows `content` beside its trigger while `open` is true. The parent owns `open`; the popover only asks to close through `onclose`. The trigger's own click handler toggles `open`, because presses on the trigger are not treated as outside presses.\n\n```svelte\n<script>\n  import Popover from 'gpuix-fractalsvelte-ui/Popover.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n  let open = $state(false);\n  let picked = $state('none');\n  const choose = (name: string) => { picked = name; open = false; };\n</script>\n\n<Popover {open} onclose={() => (open = false)} side=\"bottom\" align=\"start\">\n  <Button label=\"Menu\" variant=\"outline\" onclick={() => (open = !open)} />\n  {#snippet content()}\n    <div onclick={() => choose('Rename')}>Rename</div>\n    <div onclick={() => choose('Duplicate')}>Duplicate</div>\n  {/snippet}\n</Popover>\n\n<div>picked: {picked}</div>\n```\n\nPass `position={{ x, y }}` (window coordinates) instead of a trigger to hang the panel at a point, such as the pointer.\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `open` | `boolean` | — |   |\n| `onclose` | `() => void` | — | A press outside the panel and its trigger, or Escape. |\n| `children` | `Snippet` | — | The trigger; it toggles `open` itself. |\n| `content` | `Snippet` | — |   |\n| `side` | `'top' \\| 'right' \\| 'bottom' \\| 'left'` | `'bottom'` |   |\n| `align` | `'start' \\| 'center' \\| 'end'` | `'start'` |   |\n| `gap` | `number` | `4` |   |\n| `position` | `{ x: number; y: number } \\| null` | — | Window coordinates to hang from instead of the trigger. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Escape | Calls `onclose` while open (listened window-wide only while open) |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\timport Popover from 'gpuix-fractalsvelte-ui/Popover.svelte';\n\tlet which = $state<'actions' | 'share' | 'sort' | null>(null);\n\tlet last = $state('none');\n\tlet pinned = $state<{ x: number; y: number } | null>(null);\n\tconst choose = (name: string) => {\n\t\tlast = name;\n\t\twhich = null;\n\t};\n\tconst row = 'padding: 6px 10px; border-radius: var(--radius-sm); color: var(--text-primary); font-size: var(--text-md)';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: start\">\n\t\t<Popover open={which === 'actions'} onclose={() => (which = null)}>\n\t\t\t<Button label=\"Actions\" variant=\"outline\" onclick={() => (which = which === 'actions' ? null : 'actions')} />\n\t\t\t{#snippet content()}\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Rename')}>Rename</div>\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Duplicate')}>Duplicate</div>\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Move to…')}>Move to…</div>\n\t\t\t{/snippet}\n\t\t</Popover>\n\t\t<Popover open={which === 'share'} onclose={() => (which = null)} side=\"right\" align=\"start\">\n\t\t\t<Button label=\"Share\" variant=\"themed\" onclick={() => (which = which === 'share' ? null : 'share')} />\n\t\t\t{#snippet content()}\n\t\t\t\t<div style=\"display: flex; flex-direction: column; gap: 8px; padding: 6px; width: 200px\">\n\t\t\t\t\t<div style=\"font-size: var(--text-md); font-weight: 600; color: var(--text-primary)\">Share link</div>\n\t\t\t\t\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">Anyone with the link can view.</div>\n\t\t\t\t\t<Button label=\"Copy link\" size=\"h-md\" full onclick={() => choose('Copied link')} />\n\t\t\t\t</div>\n\t\t\t{/snippet}\n\t\t</Popover>\n\t\t<Popover open={which === 'sort'} onclose={() => (which = null)} side=\"top\" align=\"end\">\n\t\t\t<Button label=\"Sort\" variant=\"secondary\" onclick={() => (which = which === 'sort' ? null : 'sort')} />\n\t\t\t{#snippet content()}\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Name')}>Name</div>\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Date modified')}>Date modified</div>\n\t\t\t\t<div style={row} hover=\"background-color: var(--bg-raised)\" onclick={() => choose('Size')}>Size</div>\n\t\t\t{/snippet}\n\t\t</Popover>\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: start\">\n\t\t<Popover open={pinned !== null} onclose={() => (pinned = null)} position={pinned}>\n\t\t\t<Button label=\"Panel at the pointer\" variant=\"secondary\" onclick={(e) => (pinned = pinned ? null : { x: e.x ?? 0, y: e.y ?? 0 })} />\n\t\t\t{#snippet content()}<div style={row} onclick={() => choose('Pinned item')}>Pinned at the click</div>{/snippet}\n\t\t</Popover>\n\t</div>\n\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">last choice: {last}</div>\n</div>\n```\n\n## GPUI notes\n\n- The panel is a fixed 1px border, 4px padding and 160px minimum width. Override width or padding through `style`.\n- Outside-press detection uses the trigger's painted bounds, so a press on the trigger reaches its own click handler rather than closing the panel first.\n- Use `position` for a menu opened at the pointer, with no trigger element to anchor to.", demo: Popover },
	{ name: 'Toast', category: 'overlays', description: "Stacked notifications shown bottom-right, raised with the toast() function and dismissed by timer or close button.", docs: "`Toast` renders the notification stack for the `toast()` queue. Mount one `Toast` once in the app, then call `toast()` from anywhere. The queue is module-level state, so every call shows in that one stack.\n\n```svelte\n<script>\n  import Toast from 'gpuix-fractalsvelte-ui/Toast.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n  import { toast } from 'gpuix-fractalsvelte-ui/toast.svelte.ts';\n</script>\n\n<Button label=\"Save\" onclick={() => toast('Project saved', { title: 'Saved', variant: 'success' })} />\n<Button label=\"Upload\" variant=\"danger\" onclick={() => toast('Upload failed', { variant: 'danger', duration: 0 })} />\n\n<Toast />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `style` | `string \\| null` | — | Inline CSS for the stack, which sits bottom-right by default. |\n| `testid` | `string \\| null` | — |   |\n## toast()\n\n`toast(message, options)` adds a toast and returns its numeric id. `dismiss(id)` removes one early. Both come from `gpuix-fractalsvelte-ui/toast.svelte.ts`, not `Toast.svelte`.\n\n| Argument / option | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `message` | `string` | — | Required. Body text. |\n| `title` | `string` | `''` | Bold line above the message. Omitted when empty. |\n| `variant` | `'secondary' \\| 'themed' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'secondary'` | Colour of the left bar. |\n| `duration` | `number` | `4000` | Milliseconds until it dismisses itself. `0` keeps it until closed. |\n\n`dismiss(id: number)` clears the toast's timer and removes it. Closing a toast from its ✕ button does the same.\n\n`toasts` is the reactive array behind the stack, exported from the same module if you need to read the queue.\n\n## Tokens\n\n`bg-raised`, `bg-sunken`, `border`, `border-strong`, `danger`, `info`, `radius-md`, `radius-sm`, `success`, `text-md`, `text-primary`, `text-secondary`, `text-sm`, `theme-color`, `warning`\n## Keyboard\n\nNone. The ✕ button is a pointer target only.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\timport Toast from 'gpuix-fractalsvelte-ui/Toast.svelte';\n\timport { toast, toasts, dismiss } from 'gpuix-fractalsvelte-ui/toast.svelte.ts';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"Accent\" variant=\"themed\" onclick={() => toast('A new version is ready to install.', { title: 'Update', variant: 'themed' })} />\n\t\t<Button label=\"Neutral\" variant=\"secondary\" onclick={() => toast('Changes are saved to this device.', { title: 'Saved' })} />\n\t\t<Button label=\"Success\" variant=\"success\" onclick={() => toast('Your export finished in 4 seconds.', { title: 'Export complete', variant: 'success' })} />\n\t\t<Button label=\"Warn\" variant=\"warning\" onclick={() => toast('Storage is 90% full.', { title: 'Heads up', variant: 'warning' })} />\n\t\t<Button label=\"Danger\" variant=\"danger\" onclick={() => toast('The upload stopped. Check your connection.', { title: 'Upload failed', variant: 'danger', duration: 0 })} />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"Clear all\" variant=\"ghost\" size=\"h-md\" onclick={() => toasts.forEach((t) => dismiss(t.id))} />\n\t\t<div style=\"font-size: var(--text-sm); color: var(--text-secondary)\">{toasts.length} showing · the danger toast stays until closed</div>\n\t</div>\n\t<Toast />\n</div>\n```\n\n## GPUI notes\n\n- The stack is 320px wide and sits 16px from the bottom-right corner of the window. It renders through `Portal`, so placement in the tree does not matter.\n- Toasts fade in over 0.2s on mount. There is no fade-out, so a dismissed toast disappears at once.\n- Timers run in the JavaScript side. A `duration: 0` toast will sit in the stack until its ✕ is pressed or `dismiss` is called.", demo: Toast },
	{ name: 'Tooltip', category: 'overlays', description: "Short hover hint beside a trigger, shown after a delay and hidden when the pointer leaves.", docs: "`Tooltip` shows `content` next to its trigger after the pointer has rested on it for `delay` milliseconds. The trigger is a snippet that receives hover handlers, which it must spread onto its element so hover is tracked.\n\n```svelte\n<script>\n  import Tooltip from 'gpuix-fractalsvelte-ui/Tooltip.svelte';\n  import Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n</script>\n\n<Tooltip content=\"Save (cmd-s)\" side=\"bottom\">\n  {#snippet children(hover)}\n    <div {...hover}>Save</div>\n  {/snippet}\n</Tooltip>\n\n<Tooltip content=\"Delete\" open={confirming}>\n  {#snippet children(hover)}\n    <div {...hover}><Button label=\"Delete\" variant=\"danger\" /></div>\n  {/snippet}\n</Tooltip>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet<[{ onmouseenter: () => void; onmouseleave: () => void }]>` | — | The trigger; spread the handlers it receives onto it so hover still works. |\n| `content` | `string \\| Snippet` | — |   |\n| `side` | `'top' \\| 'right' \\| 'bottom' \\| 'left'` | `'top'` |   |\n| `align` | `'start' \\| 'center' \\| 'end'` | `'center'` |   |\n| `gap` | `number` | `6` |   |\n| `delay` | `number` | `300` | ms of hover before the tip shows. |\n| `open` | `boolean \\| null` | — | Forces the tip shown or hidden; `null` leaves it to hover. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\nNone; the component takes its colours from the element it sits in.\n## Keyboard\n\nNone.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Tooltip from 'gpuix-fractalsvelte-ui/Tooltip.svelte';\n\tconst trigger = 'padding: 6px 12px; border-radius: var(--radius-sm); background-color: var(--bg-raised); color: var(--text-primary); font-size: var(--text-md)';\n\tconst hover = 'background-color: var(--border)';\n\tconst caption = 'font-size: var(--text-sm); color: var(--text-secondary)';\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 24px; padding-top: 44px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center; justify-content: center\">\n\t\t{#each ['top', 'right', 'bottom', 'left'] as const as side}\n\t\t\t<Tooltip content={`Shown on the ${side}`} {side} delay={150}>\n\t\t\t\t{#snippet children(h)}\n\t\t\t\t\t<div {...h} style={trigger} {hover}>{side}</div>\n\t\t\t\t{/snippet}\n\t\t\t</Tooltip>\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center\">\n\t\t<Tooltip content=\"Save (⌘S)\" delay={150}>\n\t\t\t{#snippet children(h)}\n\t\t\t\t<div {...h} style={trigger} {hover}>Save</div>\n\t\t\t{/snippet}\n\t\t</Tooltip>\n\t\t<Tooltip content=\"Forced open\" open={true} side=\"bottom\">\n\t\t\t{#snippet children(h)}\n\t\t\t\t<div {...h} style={trigger} {hover}>Pinned</div>\n\t\t\t{/snippet}\n\t\t</Tooltip>\n\t\t<div style={caption}>Hover the buttons. \"Pinned\" is forced open.</div>\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- A trigger with its own listener would cover the wrapper's hover, so the trigger must receive the handlers and spread them itself.\n- Hover is tracked per source (wrapper, trigger, tip). Leaving the trigger hides the tip after an 80 ms grace period, which lets the pointer cross the gap onto the tip.\n- The tip hangs from explicit corners rather than GPUI's `align: center`, which lands half a layer off.\n- Clicks on the trigger still reach its own handlers, since the tip is only hover-driven.", demo: Tooltip },
	{ name: 'Alert', category: 'feedback', description: "Inline status message with a variant, optional title and a dismiss control.", docs: "`Alert` shows a message in a tinted box with a coloured dot. Pass `onclose` to add a ✕ control; the parent removes the alert when it runs.\n\n```svelte\n<script>\n  import Alert from 'gpuix-fractalsvelte-ui/Alert.svelte';\n  let saved = $state(true);\n</script>\n\n{#if saved}\n  <Alert title=\"Saved\" variant=\"success\" onclose={() => (saved = false)}>Your changes are live.</Alert>\n{/if}\n<Alert variant=\"danger\">Sync failed: the server did not respond.</Alert>\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `title` | `string` | `''` |   |\n| `variant` | `'info' \\| 'secondary' \\| 'success' \\| 'warning' \\| 'danger'` | `'info'` | Fractalstyler's status names. |\n| `children` | `Snippet` | — | Body content under the title. |\n| `onclose` | `() => void` | — | Shows a dismiss button; the parent removes the alert. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `border-strong`, `danger`, `danger-soft`, `info`, `info-soft`, `radius-full`, `radius-md`, `radius-sm`, `ring`, `success`, `success-soft`, `text-primary`, `text-secondary`, `text-sm`, `warning`, `warning-soft`\n## Keyboard\n\n| Key | Action |\n| --- | --- |\n| Enter, Space | Dismiss, while the ✕ control is focused |\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Alert from 'gpuix-fractalsvelte-ui/Alert.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tlet shown = $state(true);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px; width: 460px\">\n\t{#if shown}\n\t\t<Alert title=\"Export complete\" variant=\"success\" onclose={() => (shown = false)}>Saved 12 files to ~/Documents/export.</Alert>\n\t{/if}\n\t<Alert title=\"Update available\" variant=\"info\">Version 1.4 adds faster search.</Alert>\n\t<Alert title=\"Disk almost full\" variant=\"warning\">Free some space before exporting.</Alert>\n\t<Alert title=\"Sync failed\" variant=\"danger\">The server did not respond. Try again.</Alert>\n\t<Alert variant=\"secondary\">Plain note without a title.</Alert>\n\t{#if !shown}\n\t\t<Button label=\"Show again\" size=\"h-md\" variant=\"outline\" onclick={() => (shown = true)} />\n\t{/if}\n</div>\n```\n\n## GPUI notes\n\n- The ✕ is a focusable `div`, not a button. Its focus ring is a border colour change, since GPUI has no outline.\n- The ✕ has its own `onclick`, so clicking it does not reach any ancestor handlers.", demo: Alert },
	{ name: 'Avatar', category: 'feedback', description: "Circle or square user image, falling back to initials from a name.", docs: "`Avatar` shows a picture when `src` is set, and otherwise the initials of `name` on a tinted background.\n\n```svelte\n<script>\n  import Avatar from 'gpuix-fractalsvelte-ui/Avatar.svelte';\n</script>\n\n<Avatar name=\"Ada Lovelace\" />\n<Avatar name=\"Grace Hopper\" size=\"lg\" shape=\"square\" />\n<Avatar name=\"Linus\" src=\"/avatars/linus.png\" size=\"sm\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `name` | `string` | `''` | Initials come from the first and last word. |\n| `src` | `string \\| null` | — | Image path or URL; the initials show while it is unset. |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` |   |\n| `shape` | `'circle' \\| 'square'` | `'circle'` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`theme-color`, `theme-color-sub`\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Avatar from 'gpuix-fractalsvelte-ui/Avatar.svelte';\n\tconst PEOPLE = ['Ada Lovelace', 'Grace Hopper', 'Alan Turing'];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 12px; align-items: center\">\n\t\t<Avatar name=\"Ada Lovelace\" size=\"sm\" />\n\t\t<Avatar name=\"Ada Lovelace\" />\n\t\t<Avatar name=\"Ada Lovelace\" size=\"lg\" />\n\t\t<Avatar name=\"Ada Lovelace\" size=\"lg\" shape=\"square\" />\n\t\t<Avatar name=\"Grace Hopper\" src=\"data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAgAAAAICAIAAABLbSncAAAAgElEQVR4nA3JIQFFMQhA0R/n1VgNGqAxa4CZXgMaoDGEwNwwf8ee3ycsQQQTjhBCCSP8PmUpophylFBKGX2xWRvZ2OZsYlOb2S+c5YhjznHCKWf8xWVd5GKXc4lLXea+CFYggQUniKCCiRfJSiSx5CSRVDL5olmNNNacJppqpvkDd6t6gRN3ZoUAAAAASUVORK5CYII=\" size=\"lg\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each PEOPLE as person}\n\t\t\t<Avatar name={person} />\n\t\t{/each}\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- The image is drawn with `objectfit=\"cover\"` inside a root that sets `overflow: hidden`, so it is clipped to the circle or square.\n- When `src` is set the initials are not rendered, and the component has no fallback if the image fails to load.", demo: Avatar },
	{ name: 'Badge', category: 'feedback', description: "Small pill label for counts, statuses and tags, in five variants and three variants.", docs: "`Badge` is a non-interactive pill. Use `label` for plain text, or pass children for rich content.\n\n```svelte\n<script>\n  import Badge from 'gpuix-fractalsvelte-ui/Badge.svelte';\n</script>\n\n<Badge label=\"New\" variant=\"themed\" />\n<Badge label=\"3 errors\" variant=\"danger\" />\n<Badge label=\"Draft\" size=\"h-sm\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `children` | `Snippet` | — | Content; `label` is the plain-text shorthand. |\n| `label` | `string` | `''` |   |\n| `variant` | `'secondary' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'secondary'` | Fractalstyler's status names, drawn as a tinted pill. |\n| `size` | `'sm' \\| 'md'` | `'md'` |   |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `danger`, `danger-soft`, `info`, `info-soft`, `radius-full`, `success`, `success-soft`, `text-secondary`, `text-sm`, `text-xs`, `warning`, `warning-soft`\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Badge from 'gpuix-fractalsvelte-ui/Badge.svelte';\n\tconst VARIANTS = ['secondary', 'info', 'success', 'warning', 'danger'] as const;\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t{#each VARIANTS as variant}\n\t\t\t<Badge {variant} label={variant} />\n\t\t{/each}\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Badge size=\"sm\" label=\"Small\" />\n\t\t<Badge size=\"md\" label=\"Medium\" />\n\t\t<Badge variant=\"success\" label=\"Live\" />\n\t\t<Badge variant=\"danger\" label=\"3 errors\" />\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- Each variant is its own class (`.badge.danger`), because GPUI has no nesting.\n- The base rule sets a transparent border, so only the `outline` variant shows a border.", demo: Badge },
	{ name: 'Kbd', category: 'feedback', description: "Keyboard shortcut caps for a chord such as cmd+k, drawn with macOS glyphs.", docs: "`Kbd` displays a shortcut. It is display only: it does not bind the key. Wire the shortcut with `on_window_key` yourself.\n\n```svelte\n<script>\n  import Kbd from 'gpuix-fractalsvelte-ui/Kbd.svelte';\n</script>\n\n<Kbd keys=\"cmd+k\" />\n<Kbd keys=\"shift+enter\" size=\"h-sm\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `keys` | `string` | `''` | A chord such as `cmd+k` or `shift+enter`; each part becomes one cap. |\n| `size` | `'h-sm' \\| 'h-md'` | `'h-md'` | Fractalstyler's height steps. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `border-strong`, `height-md`, `radius-sm`, `text-secondary`\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Kbd from 'gpuix-fractalsvelte-ui/Kbd.svelte';\n\tconst SHORTCUTS = [\n\t\t['Command palette', 'cmd+k'],\n\t\t['Save', 'cmd+s'],\n\t\t['Find in page', 'cmd+shift+f'],\n\t\t['Send message', 'shift+enter'],\n\t\t['Close dialog', 'esc']\n\t];\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n\t{#each SHORTCUTS as [action, keys]}\n\t\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center; justify-content: space-between\">\n\t\t\t<div style=\"color: var(--text-secondary)\">{action}</div>\n\t\t\t<Kbd {keys} />\n\t\t</div>\n\t{/each}\n\t<div style=\"display: flex; flex-direction: row; gap: 16px; align-items: center\">\n\t\t<Kbd keys=\"cmd+k\" size=\"h-sm\" />\n\t\t<Kbd keys=\"up\" size=\"h-sm\" />\n\t\t<Kbd keys=\"down\" size=\"h-sm\" />\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- Each cap has a 2px bottom border, which gives the key its raised look.\n- `+` splits the chord, so the literal `+` key cannot be shown.", demo: Kbd },
	{ name: 'Progress', category: 'feedback', description: "Horizontal progress bar for a known percentage, or an indeterminate sweep.", docs: "`Progress` shows how far a task has got, or that it is busy when the length is unknown.\n\n```svelte\n<script>\n  import Progress from 'gpuix-fractalsvelte-ui/Progress.svelte';\n  let value = $state(40);\n</script>\n\n<Progress {value} />\n<Progress {value} variant=\"success\" size=\"h-md\" />\n<Progress indeterminate />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `value` | `number` | `0` | 0 to 100; out-of-range values are clamped. |\n| `indeterminate` | `boolean` | `false` | Ignores `value` and sweeps a segment back and forth. |\n| `variant` | `'themed' \\| 'secondary' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'themed'` | Fractalstyler's colour names. |\n| `size` | `'sm' \\| 'md' \\| 'lg'` | `'md'` | Bar thickness: 4, 6 or 8 px. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`bg-raised`, `danger`, `info`, `radius-full`, `success`, `text-secondary`, `theme-color`, `warning`\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Progress from 'gpuix-fractalsvelte-ui/Progress.svelte';\n\timport Button from 'gpuix-fractalsvelte-ui/Button.svelte';\n\tlet value = $state(35);\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 14px; width: 420px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 8px; align-items: center\">\n\t\t<Button label=\"-10\" size=\"h-md\" variant=\"outline\" onclick={() => (value = Math.max(0, value - 10))} />\n\t\t<Button label=\"+10\" size=\"h-md\" variant=\"outline\" onclick={() => (value = Math.min(100, value + 10))} />\n\t\t<div style=\"color: var(--text-secondary)\">{value}%</div>\n\t</div>\n\t<Progress {value} size=\"sm\" />\n\t<Progress {value} />\n\t<Progress {value} size=\"lg\" variant=\"success\" />\n\t<Progress {value} variant=\"warning\" />\n\t<Progress {value} variant=\"danger\" />\n\t<Progress indeterminate />\n</div>\n```\n\n## GPUI notes\n\n- The determinate fill is `width` as a percentage, which GPUI allows on `width`.\n- Indeterminate mode runs a 30 ms interval that re-renders the component while `indeterminate` is true. The timer is cleared when it turns off or the component unmounts.\n- The track has `overflow: hidden`, so the fill is clipped to its rounded ends.", demo: Progress },
	{ name: 'Spinner', category: 'feedback', description: "Indeterminate loading indicator drawn as a ring of fading dots.", docs: "`Spinner` shows ongoing work with no progress value. It draws eight dots in a ring and steps the bright lead dot around it on a timer.\n\n```svelte\n<script>\n  import Spinner from 'gpuix-fractalsvelte-ui/Spinner.svelte';\n</script>\n\n<Spinner />\n<Spinner size=\"h-sm\" />\n<Spinner size=\"h-lg\" variant=\"success\" testid=\"saving\" />\n```\n\n## Props\n\n| Prop | Type | Default | Notes |\n| --- | --- | --- | --- |\n| `size` | `'h-sm' \\| 'h-md' \\| 'h-bs' \\| 'h-lg'` | `'h-bs'` | Fractalstyler's height steps; the ring fits that size. |\n| `variant` | `'themed' \\| 'secondary' \\| 'info' \\| 'success' \\| 'warning' \\| 'danger'` | `'themed'` | Dot colour, in fractalstyler's names. |\n| `style` | `string \\| null` | — |   |\n| `testid` | `string \\| null` | — |   |\n## Tokens\n\n`danger`, `height-bs`, `height-lg`, `height-md`, `height-sm`, `info`, `radius-full`, `success`, `text-secondary`, `theme-color`, `warning`\n## Keyboard\n\nNone.\n\n## Examples\n\nEvery variant, size and state, exactly as the gallery's Demo view renders them.\n\n```svelte\n<script lang=\"ts\">\n\timport Spinner from 'gpuix-fractalsvelte-ui/Spinner.svelte';\n\tconst VARIANTS = ['themed', 'secondary', 'success', 'warning', 'danger'] as const;\n</script>\n\n<div style=\"display: flex; flex-direction: column; gap: 16px\">\n\t<div style=\"display: flex; flex-direction: row; gap: 20px; align-items: center\">\n\t\t<Spinner size=\"h-sm\" />\n\t\t<Spinner size=\"h-md\" />\n\t\t<Spinner size=\"h-lg\" />\n\t</div>\n\t<div style=\"display: flex; flex-direction: row; gap: 20px; align-items: center\">\n\t\t{#each VARIANTS as variant}\n\t\t\t<Spinner {variant} size=\"h-lg\" />\n\t\t{/each}\n\t</div>\n</div>\n```\n\n## GPUI notes\n\n- GPUI has no looping motion, so the animation is a 90 ms timer that moves the lead dot. Each dot is absolutely positioned with a stepped opacity.\n- The timer runs while the spinner is mounted. Unmount it when the work is done.", demo: Spinner },
];
